repair_installed_template_from_installer() {
    local template_name="$1"
    local destination="$APP/web/templates/$template_name"

    if [ ! -f "$0" ] || [ ! -x "$VENV/bin/python" ]; then
        echo "ERROR: Installer source or Python runtime is unavailable." >&2
        return 1
    fi

    mkdir -p "$(dirname "$destination")" || return 1

    echo "Refreshing installed template from installer: $template_name"
    if ! "$VENV/bin/python" - "$0" "$destination" "$template_name" << 'PYTHON_TEMPLATE_REPAIR'
import sys
from pathlib import Path

installer_path = Path(sys.argv[1])
destination_path = Path(sys.argv[2])
template_name = sys.argv[3]

source = installer_path.read_text(encoding='utf-8', errors='ignore')
marker = f"cat > $APP/web/templates/{template_name} << 'EOF'\n"
start = source.find(marker)
if start < 0:
    raise SystemExit(f'template marker not found: {template_name}')

start += len(marker)
end = source.find('\nEOF\n', start)
if end < 0:
    raise SystemExit(f'template terminator not found: {template_name}')

template_source = source[start:end] + '\n'
destination_path.write_text(template_source, encoding='utf-8')
print(f'updated {destination_path}')
PYTHON_TEMPLATE_REPAIR
    then
        echo "ERROR: Unable to refresh installed template $template_name from this installer." >&2
        return 1
    fi
}

repair_installed_app_file_from_installer() {
    local relative_path="$1"
    # Second argument picks the heredoc prefix: files under app/ use $APP,
    # while main.py sits one level up under $BASE. Without this main.py was
    # never refreshed, so fixes living there silently never reached an
    # installed system.
    local marker_prefix="${2:-\$APP}"
    local base_dir="$APP"
    if [ "$marker_prefix" = "\$BASE" ]; then
        base_dir="$BASE"
    fi
    local destination="$base_dir/$relative_path"

    if [ ! -f "$0" ] || [ ! -x "$VENV/bin/python" ]; then
        echo "ERROR: Installer source or Python runtime is unavailable." >&2
        return 1
    fi

    mkdir -p "$(dirname "$destination")" || return 1

    echo "Refreshing installed app file from installer: $relative_path"
    if ! "$VENV/bin/python" - "$0" "$destination" "$relative_path" "$marker_prefix" << 'PYTHON_APP_FILE_REPAIR'
import sys
from pathlib import Path

installer_path = Path(sys.argv[1])
destination_path = Path(sys.argv[2])
relative_path = sys.argv[3]
marker_prefix = sys.argv[4] if len(sys.argv) > 4 else '$APP'

source = installer_path.read_text(encoding='utf-8', errors='ignore')
marker = f"cat > {marker_prefix}/{relative_path} << 'EOF'\n"
start = source.find(marker)
if start < 0:
    raise SystemExit(f'app file marker not found: {relative_path}')

start += len(marker)
end = source.find('\nEOF\n', start)
if end < 0:
    raise SystemExit(f'app file terminator not found: {relative_path}')

destination_path.write_text(source[start:end] + '\n', encoding='utf-8')
print(f'updated {destination_path}')
PYTHON_APP_FILE_REPAIR
    then
        echo "ERROR: Unable to refresh installed app file $relative_path from this installer." >&2
        return 1
    fi
}

run_self_test() {
    # Non-destructive consistency check: confirms the expected files, systemd
    # service, templates, database schema and runtime health endpoint are all
    # present and coherent, without touching any running services. Meant as a
    # quick post-install / post-repair verification and troubleshooting aid.
    echo "=== GNSS CASTER SELF-TEST MODE ==="
    echo "Checking installed files, services, templates, database, and runtime health..."

    local failures=0
    local warnings=0
    local web_port
    local ntrip_port
    local health_url

    pass_check() {
        echo "PASS: $*"
    }

    warn_check() {
        warnings=$((warnings + 1))
        echo "WARN: $*"
    }

    fail_check() {
        failures=$((failures + 1))
        echo "FAIL: $*"
    }

    check_command_available() {
        local command_name="$1"
        if command -v "$command_name" >/dev/null 2>&1; then
            pass_check "command available: $command_name"
        else
            warn_check "command unavailable: $command_name"
        fi
    }

    check_file_present() {
        local path="$1"
        local label="$2"
        if [ -f "$path" ]; then
            pass_check "$label present: $path"
        else
            fail_check "$label missing: $path"
        fi
    }

    check_dir_present() {
        local path="$1"
        local label="$2"
        if [ -d "$path" ]; then
            pass_check "$label present: $path"
        else
            fail_check "$label missing: $path"
        fi
    }

    check_command_available python3
    check_command_available sqlite3
    check_command_available nginx
    check_command_available systemctl
    check_command_available curl
    check_command_available ss

    check_dir_present "$BASE" "base directory"
    check_dir_present "$APP" "application directory"
    check_dir_present "$INST" "instance directory"
    check_dir_present "$LOG_DIR" "log directory"
    check_file_present "$BASE/main.py" "main entrypoint"
    check_file_present "$APP/version.py" "version module"
    check_file_present "$APP/web/factory.py" "Flask factory"
    check_file_present "$APP/web/templates/base_stations.html" "base stations template"
    check_file_present "$APP/web/templates/system_configuration.html" "system configuration template"
    check_file_present "$APP/web/templates/station_detail.html" "station detail template"
    check_file_present "$APP/web/templates/login_2fa.html" "2FA login template"
    check_file_present "$APP/web/static/ui/manifest.json" "React web assets"
    check_file_present "$INST/config.yaml" "runtime config"
    check_file_present "$SERVICE" "systemd service"

    if [ -x "$VENV/bin/python" ]; then
        pass_check "virtualenv Python executable present: $VENV/bin/python"
        if "$VENV/bin/python" - << 'PYTHON_SELF_TEST' >/tmp/gnss-caster-selftest-python.log 2>&1
import sys
sys.path.insert(0, '/opt/gnss-caster')
from sqlalchemy import text
from app.web.factory import create_app
from app.db.models import db, BaseStation, SystemSetting

app = create_app()
with app.app_context():
    db.session.execute(text('SELECT 1'))
    BaseStation.query.count()
    SystemSetting.query.count()
print('python_app_import_ok')
PYTHON_SELF_TEST
        then
            pass_check "Python app imports and database query succeeded"
        else
            fail_check "Python app import/database check failed"
            tail -n 20 /tmp/gnss-caster-selftest-python.log 2>/dev/null | sed 's/^/  /' || true
        fi
    else
        fail_check "virtualenv Python executable missing: $VENV/bin/python"
    fi

    if [ -f "$INST/db.sqlite" ] && command -v sqlite3 >/dev/null 2>&1; then
        if sqlite3 "$INST/db.sqlite" 'PRAGMA integrity_check;' 2>/dev/null | grep -qx 'ok'; then
            pass_check "SQLite integrity check passed"
        else
            fail_check "SQLite integrity check failed"
        fi
    else
        warn_check "SQLite integrity check skipped"
    fi

    if [ -f "$NGINX_AVAILABLE" ] && command -v nginx >/dev/null 2>&1; then
        if nginx -t >/tmp/gnss-caster-selftest-nginx.log 2>&1; then
            pass_check "nginx configuration test passed"
        else
            fail_check "nginx configuration test failed"
            tail -n 20 /tmp/gnss-caster-selftest-nginx.log 2>/dev/null | sed 's/^/  /' || true
        fi
    else
        warn_check "nginx test skipped; site or nginx command not found"
    fi

    if [ -f "$SERVICE" ] && command -v systemd-analyze >/dev/null 2>&1; then
        if systemd-analyze verify "$SERVICE" >/tmp/gnss-caster-selftest-systemd.log 2>&1; then
            pass_check "systemd unit verification passed"
        else
            warn_check "systemd unit verification reported issues"
            tail -n 20 /tmp/gnss-caster-selftest-systemd.log 2>/dev/null | sed 's/^/  /' || true
        fi
    fi

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")
    health_url="http://127.0.0.1:${web_port}/api/health"

    if command -v systemctl >/dev/null 2>&1; then
        if systemctl is-active --quiet gnss-caster; then
            pass_check "gnss-caster service is active"
        else
            warn_check "gnss-caster service is not active"
        fi
    fi

    if command -v curl >/dev/null 2>&1; then
        if curl -sS --max-time 5 -f "$health_url" >/dev/null 2>&1; then
            pass_check "backend health endpoint responded: $health_url"
        else
            warn_check "backend health endpoint did not respond: $health_url"
        fi
    fi

    if is_tcp_port_listening "$ntrip_port"; then
        pass_check "NTRIP port is listening: $ntrip_port"
    else
        warn_check "NTRIP port is not listening: $ntrip_port"
    fi

    # Validate the installer script itself so syntax regressions are caught.
    if [ -f "$0" ]; then
        if bash -n "$0" >/tmp/gnss-caster-selftest-bashn.log 2>&1; then
            pass_check "installer bash syntax check passed: $0"
        else
            fail_check "installer bash syntax check failed: $0"
            tail -n 20 /tmp/gnss-caster-selftest-bashn.log 2>/dev/null | sed 's/^/  /' || true
        fi

        if command -v shellcheck >/dev/null 2>&1; then
            if shellcheck -S error "$0" >/tmp/gnss-caster-selftest-shellcheck.log 2>&1; then
                pass_check "shellcheck reported no error-level issues"
            else
                warn_check "shellcheck reported error-level issues"
                tail -n 20 /tmp/gnss-caster-selftest-shellcheck.log 2>/dev/null | sed 's/^/  /' || true
            fi
        else
            warn_check "shellcheck not installed; static lint skipped"
        fi
    fi

    echo ""
    echo "Self-test summary: failures=$failures warnings=$warnings"

    if [ "$failures" -gt 0 ]; then
        exit 1
    fi
}

repair_privileged_port() {
    # repair_privileged_port CONFIG_KEY VAR_NAME DEFAULT_PORT
    # Rewrites a privileged/invalid port in config.yaml back to DEFAULT_PORT and
    # updates the in-memory variable, so --repair can recover an install whose
    # service cannot start because it was configured to bind a port below 1024.
    local config_key="$1"
    local var_name="$2"
    local default_port="$3"
    local current_value="${!var_name}"
    local config_file="$INST/config.yaml"

    case "$current_value" in
        ''|*[!0-9]*) : ;;
        *) [ "$current_value" -ge 1024 ] && [ "$current_value" -le 65535 ] && return 0 ;;
    esac

    echo "Repairing unusable $config_key '$current_value' -> $default_port (ports below 1024 cannot be bound by the unprivileged service)."
    printf -v "$var_name" '%s' "$default_port"

    if [ -f "$config_file" ]; then
        sed -i -E "s|^([[:space:]]*)${config_key}:[[:space:]]*.*$|\1${config_key}: ${default_port}|" "$config_file"
    fi
}

run_repair() {
    echo "=== GNSS CASTER REPAIR MODE ==="
    echo "Repairing permissions, service files, nginx wiring, cron, logrotate, and database schema..."

    if [ ! -d "$BASE" ]; then
        echo "ERROR: GNSS Caster base directory not found: $BASE"
        echo "Run full installation first."
        exit 1
    fi

    if [ ! -x "$VENV/bin/python" ] || [ ! -f "$BASE/main.py" ]; then
        echo "ERROR: GNSS Caster runtime is incomplete under $BASE"
        echo "Run full installation first."
        exit 1
    fi

    begin_runtime_transaction

    INSTALL_WEB_PORT=$(get_config_value "web_port" "$INSTALL_WEB_PORT")
    INSTALL_NTRIP_PORT=$(get_config_value "ntrip_port" "$INSTALL_NTRIP_PORT")
    # An installed config may carry a privileged port (e.g. 443 entered as the
    # web port), which the unprivileged service can never bind - it dies with
    # "PermissionError: [Errno 13]". Repair is meant to fix exactly this, so
    # rewrite such a value back to a working default instead of refusing to run.
    repair_privileged_port "web_port" "INSTALL_WEB_PORT" "8080"
    repair_privileged_port "ntrip_port" "INSTALL_NTRIP_PORT" "2101"
    validate_install_ports

    mkdir -p "$APP" "$INST" "$BACKUP_DIR" "$LOG_DIR"
    if [ -f "$0" ]; then
        cp -f "$0" "$BASE/gnss-caster-installer.sh"
        chmod 700 "$BASE/gnss-caster-installer.sh" 2>/dev/null || true
    fi

    declare -f sqlite_database_tool acquire_maintenance_lock > "$BASE/sqlite-functions.sh"
    chown root:root "$BASE/sqlite-functions.sh"
    chmod 600 "$BASE/sqlite-functions.sh"

    ensure_service_account
    write_privileged_helper
    write_polkit_bluetooth_rule
    write_ufw_application_profile
    write_watchdog_script
    # Refresh the Python dependencies. Repaired code may require packages that
    # a previous install never had (this is how BLE support silently failed
    # after an upgrade: bleak was missing from the existing virtualenv).
    # The on-disk requirements.txt belongs to the *old* install, so rewrite it
    # from this installer first, then sync.
    if [ -x "$VENV/bin/python" ] && [ -f "$0" ]; then
        echo "Synchronising Python dependencies..."
        if "$VENV/bin/python" - "$0" "$BASE/requirements.txt" << 'PYTHON_REQUIREMENTS_REPAIR'
import sys
from pathlib import Path

installer_path = Path(sys.argv[1])
destination_path = Path(sys.argv[2])

source = installer_path.read_text(encoding='utf-8', errors='ignore')
marker = "cat > $BASE/requirements.txt << 'EOF'\n"
start = source.find(marker)
if start < 0:
    raise SystemExit('requirements marker not found')

start += len(marker)
end = source.find('\nEOF\n', start)
if end < 0:
    raise SystemExit('requirements block is not terminated')

body = source[start:end] + '\n'
if not body.strip():
    raise SystemExit('extracted requirements block is empty')

destination_path.write_text(body, encoding='utf-8')
PYTHON_REQUIREMENTS_REPAIR
        then
            :
        else
            echo "ERROR: Could not refresh locked requirements; stopping repair."
            return 1
        fi

        if [ -f "$BASE/requirements.txt" ]; then
            if ! "$VENV/bin/python" -m pip install --require-hashes -r "$BASE/requirements.txt"; then
                echo "ERROR: Locked dependency installation failed; stopping repair."
                return 1
            fi
            "$VENV/bin/python" -m pip check || return 1
        fi
    fi

    # Refresh every application module, not just a couple of them: a partial
    # list silently strands fixes in the modules that are missing from it
    # (an RTCM parser fix once never reached installed systems this way).
    repair_installed_app_file_from_installer "web/factory.py"
    repair_installed_app_file_from_installer "bluetooth/core.py"
    repair_installed_app_file_from_installer "ntrip/core.py"
    repair_installed_app_file_from_installer "rtcm/stream.py"
    repair_installed_app_file_from_installer "rtcm/registry.py"
    repair_installed_app_file_from_installer "notify.py"
    repair_installed_app_file_from_installer "db/models.py"
    repair_installed_app_file_from_installer "main.py" "\$BASE"

    # Helper scripts live beside main.py and are just as much part of the
    # release. Leaving them out meant backup.sh kept running the version from
    # the original install no matter how often --repair was run.
    repair_installed_app_file_from_installer "backup.sh" "\$BASE"
    repair_installed_app_file_from_installer "restore.sh" "\$BASE"
    repair_installed_app_file_from_installer "monitor.sh" "\$BASE"
    repair_installed_app_file_from_installer "update.sh" "\$BASE"
    for helper_script in backup.sh restore.sh monitor.sh update.sh; do
        chmod 700 "$BASE/$helper_script" 2>/dev/null || true
        chown root:root "$BASE/$helper_script" 2>/dev/null || true
    done
    # Regenerate the version module from CASTER_VERSION. It is generated (not a
    # heredoc block), so it cannot be re-extracted like the app files above;
    # emit it directly instead. Also upgrades installs that predate this module.
    cat > "$APP/version.py" << EOF
"""GNSS Caster application version (generated by the installer)."""
__version__ = "$CASTER_VERSION"
EOF
    repair_tls_certificate_reader
    # Every template, not a hand-picked subset: base.html was missing from the
    # list, so any fix in the shared layout or global CSS never reached an
    # installed system no matter how many times --repair was run.
    for template_name in \
        base.html \
        dashboard.html \
        base_stations.html \
        station_detail.html \
        mountpoints.html \
        rovers.html \
        rtcm_settings.html \
        system_configuration.html \
        user_settings.html \
        logs.html \
        login.html \
        login_2fa.html \
        diagnostics.html \
        backups.html \
        error.html \
        404.html \
        500.html
    do
        repair_installed_template_from_installer "$template_name"
    done
    install_react_ui

    manage_secret_files migrate
    echo "Rewriting systemd service..."
    backup_and_clear_unit_override
    write_systemd_service_unit
    ensure_valid_systemd_service_unit
    systemctl daemon-reload
    systemctl enable gnss-caster >/dev/null 2>&1 || true

    echo "Repairing nginx configuration..."
    if [ ! -f "$NGINX_AVAILABLE" ]; then
        echo "Nginx site was missing; writing HTTP reverse proxy config."
        NGINX_SERVER_NAME="${TLS_DOMAIN:-_}"
        write_nginx_http_config
    fi
    apply_nginx_config

    sync_logrotate_config
    sync_cron_jobs

    echo "Repairing database schema..."
    run_database_migrations

    set_runtime_permissions

    echo "Restarting GNSS Caster service..."
    systemctl reset-failed gnss-caster >/dev/null 2>&1 || true
    if ! systemctl restart gnss-caster; then
        echo "ERROR: Failed to restart gnss-caster.service during repair"
        echo "--- systemctl status (tail) ---"
        systemctl --no-pager --full status gnss-caster 2>/dev/null | tail -n 40 || true
        echo "--- journalctl -u gnss-caster (tail) ---"
        journalctl -u gnss-caster --since '20 minutes ago' --no-pager 2>/dev/null | tail -n 80 || true
        exit 1
    fi

    echo ""
    echo "Running post-repair health gate..."
    finish_repair_transaction

    echo ""
    echo "Repair completed. Current status:"
    run_status
}

case "$SCRIPT_MODE" in
    install|uninstall|repair|reset-admin-password|rotate-secrets|panic)
        acquire_maintenance_lock
        ;;
esac

if [ "$SCRIPT_MODE" = "uninstall" ]; then
    run_uninstall
    exit 0
fi

if [ "$SCRIPT_MODE" = "reset-admin-password" ]; then
    run_reset_admin_password
    exit 0
fi

if [ "$SCRIPT_MODE" = "repair" ]; then
    run_repair
    exit 0
fi

if [ "$SCRIPT_MODE" = "diagnose" ]; then
    run_diagnose
    exit 0
fi

if [ "$SCRIPT_MODE" = "status" ]; then
    run_status
    exit 0
fi

if [ "$SCRIPT_MODE" = "self-test" ]; then
    run_self_test
    exit 0
fi

if [ "$SCRIPT_MODE" = "rotate-secrets" ]; then
    run_rotate_secrets
    exit 0
fi

if [ "$SCRIPT_MODE" = "panic" ]; then
    run_panic
    exit 0
fi

prompt_install_options() {
    [ "$SCRIPT_MODE" = "install" ] || return
    ui_enabled || return

    local wp np
    while :; do
        wp=$(ui_input "Network ports" "Internal web backend port (nginx proxies to it; must be 1024-65535).\n\nPublic HTTP/HTTPS stays on 80/443 - do NOT enter 443 here." "$INSTALL_WEB_PORT")
        [ -n "$wp" ] || break
        if [[ "$wp" =~ ^[0-9]+$ ]] && [ "$wp" -ge 1024 ] && [ "$wp" -le 65535 ]; then
            INSTALL_WEB_PORT="$wp"; break
        fi
        ui_msgbox "Invalid port" "'$wp' is not usable.\n\nThe caster runs unprivileged, so the backend port must be between 1024 and 65535. nginx serves the public 80/443 for you - enable HTTPS with the TLS option instead of setting 443 here."
    done
    while :; do
        np=$(ui_input "Network ports" "NTRIP caster port (must be 1024-65535):" "$INSTALL_NTRIP_PORT")
        [ -n "$np" ] || break
        if [[ "$np" =~ ^[0-9]+$ ]] && [ "$np" -ge 1024 ] && [ "$np" -le 65535 ] && [ "$np" != "$INSTALL_WEB_PORT" ]; then
            INSTALL_NTRIP_PORT="$np"; break
        fi
        ui_msgbox "Invalid port" "'$np' is not usable.\n\nUse a port between 1024 and 65535 that differs from the web backend port ($INSTALL_WEB_PORT). The standard NTRIP port is 2101."
    done

    local sel
    sel=$(ui_checklist "Optional features" "Space toggles, Enter confirms:" \
        fail2ban   "Ban IPs after repeated auth failures" "$([ "$ENABLE_FAIL2BAN" = "1" ] && echo on || echo off)" \
        autoupdate "Weekly automatic update cron"         "$([ "$ENABLE_AUTO_UPDATE" = "1" ] && echo on || echo off)" \
        watchdog   "Health watchdog cron"                 "$([ "$ENABLE_WATCHDOG" = "1" ] && echo on || echo off)" \
        forcekill  "Free the runtime port if occupied"    "$([ "$FORCE_PORT_KILL" = "1" ] && echo on || echo off)")

    case " $sel " in *" fail2ban "*)   ENABLE_FAIL2BAN=1;;   *) ENABLE_FAIL2BAN=0;;   esac
    case " $sel " in *" autoupdate "*) ENABLE_AUTO_UPDATE=1;; *) ENABLE_AUTO_UPDATE=0;; esac
    case " $sel " in *" watchdog "*)   ENABLE_WATCHDOG=1;;    *) ENABLE_WATCHDOG=0;;    esac
    case " $sel " in *" forcekill "*)  FORCE_PORT_KILL=1;;    *) FORCE_PORT_KILL=0;;    esac

    local tls_summary="$TLS_MODE"
    [ -n "$TLS_DOMAIN" ] && tls_summary="$tls_summary ($TLS_DOMAIN)"
    local msg
    msg=$(printf 'Proceed with installation?\n\nWeb port:    %s\nNTRIP port:  %s\nTLS:         %s\nfail2ban:    %s\nauto-update: %s\nwatchdog:    %s' \
        "$INSTALL_WEB_PORT" "$INSTALL_NTRIP_PORT" "$tls_summary" \
        "$([ "$ENABLE_FAIL2BAN" = "1" ] && echo yes || echo no)" \
        "$([ "$ENABLE_AUTO_UPDATE" = "1" ] && echo yes || echo no)" \
        "$([ "$ENABLE_WATCHDOG" = "1" ] && echo yes || echo no)")
    if ! ui_yesno "Review" "$msg"; then
        echo "Installation cancelled."
        exit 0
    fi
}

prompt_tls_mode
prompt_install_options

echo "Checking prerequisites..."
validate_tls_config
validate_install_ports
run_preflight_checks
begin_runtime_transaction

# Ensure BlueZ and D-Bus backend are present
if ! command -v bluetoothd >/dev/null 2>&1; then
    echo "bluetoothd not found, installing bluez and dbus packages..."
    apt update && apt install -y bluez dbus
fi

if ! command -v python3 >/dev/null 2>&1; then
    echo "Python3 not found, installing..."
    apt update && apt install -y python3 python3-venv
fi

if ! command -v openssl >/dev/null 2>&1; then
    echo "OpenSSL not found, installing..."
    apt install -y openssl
fi

manage_secret_files migrate
if [ ! -f "$SECRET_KEY_ENV_FILE" ]; then
SECRET_KEY=$(openssl rand -hex 32)
# Store the key in a dedicated file (mode 600); systemd will load it via EnvironmentFile=
# This prevents the key from being visible via `systemctl show gnss-caster`.
mkdir -p "$INST"
{
    printf 'SECRET_KEY=%s\n' "$SECRET_KEY"
    # Bluetooth pairing controls live here (mode 600) so PINs are not exposed
    # via `systemctl show gnss-caster`.
    printf 'BT_DEFAULT_PIN="%s"\n' "$BT_DEFAULT_PIN"
    printf 'BT_FALLBACK_PINS="%s"\n' "$BT_FALLBACK_PINS"
    printf 'BT_AUTO_ACCEPT="%s"\n' "$BT_AUTO_ACCEPT"
    printf 'BT_ALLOWED_DEVICES="%s"\n' "$BT_ALLOWED_DEVICES"
} > "$SECRET_KEY_ENV_FILE"
chmod 600 "$SECRET_KEY_ENV_FILE"
chown root:root "$SECRET_KEY_ENV_FILE"
fi

# ----------------- PACKAGES INSTALLATION -----------------
# Install the OS package dependencies via apt: Python 3, SQLite, BlueZ/D-Bus,
# nginx, ufw, cron, logrotate and the build tools needed by the Python wheels.
echo "Installing system packages..."
apt update
apt install -y \
  python3 python3-venv python3-pip python3-dev \
  sqlite3 \
  bluez bluez-tools dbus \
  nginx curl openssl ufw \
  cron logrotate iproute2 iw \
  build-essential libssl-dev libffi-dev \
  git sudo \
  rfkill psmisc

# apt may have just installed Python on a clean host; enforce the runtime floor
# before creating the virtual environment or generating application files.
validate_python_version || exit 1

ensure_service_account
write_privileged_helper
write_polkit_bluetooth_rule

if [ "$ENABLE_FAIL2BAN" = "1" ] || [ "$FAIL2BAN_WAS_PRESENT" -eq 1 ] || [ "$FAIL2BAN_GNSS_JAIL_WAS_PRESENT" -eq 1 ]; then
    echo "Installing or refreshing fail2ban package..."
    apt install -y fail2ban
fi

if [ "$TLS_MODE" = "letsencrypt" ]; then
    echo "Installing Certbot for Let's Encrypt..."
    apt install -y certbot
fi

# Safely handle occupied runtime ports before service installation.
prepare_runtime_port "backend web" "$INSTALL_WEB_PORT"
prepare_runtime_port "NTRIP" "$INSTALL_NTRIP_PORT"

# Enable services
systemctl enable bluetooth --now
systemctl enable cron --now

# Validate bluetooth service
echo "Validating bluetooth service..."
if systemctl is-enabled bluetooth >/dev/null 2>&1; then
    echo "bluetooth service is enabled"
else
    echo "ERROR: bluetooth service is not available"
    exit 1
fi

# ----------------- DIRECTORY STRUCTURE -----------------
# Create the /opt/gnss-caster tree and the Python package layout, seed the
# log files, and generate app/version.py from CASTER_VERSION.
echo "Creating directory structure..."
mkdir -p "$APP"/{web/templates,web/static,db,rtcm,ntrip,bluetooth,core,api}
mkdir -p "$INST" "$BACKUP_DIR" "$LOG_DIR"
touch $LOG_DIR/app.log
chown root:"$SERVICE_GROUP" $LOG_DIR/app.log 2>/dev/null || true
chmod 660 $LOG_DIR/app.log 2>/dev/null || true

echo "Applying web security hardening..."
write_ufw_application_profile
setup_fail2ban
echo "UFW application profiles installed (firewall is NOT enabled automatically)."
echo "Examples:"
echo "  ufw allow 'GNSS Caster Web'"
echo "  ufw allow 'GNSS Caster NTRIP'"
echo "  ufw allow 'GNSS Caster Full'"

# Create __init__.py files
touch $APP/__init__.py
for d in web db rtcm ntrip bluetooth core api; do
  touch $APP/$d/__init__.py
done

# Generate the application version module from CASTER_VERSION (the installer's
# single source of truth). Imported by the NTRIP server for the Server header,
# so the wire protocol always reports the same version as the installer.
cat > $APP/version.py << EOF
"""GNSS Caster application version (generated by the installer)."""
__version__ = "$CASTER_VERSION"
EOF

# ----------------- CONFIGURATION FILES -----------------
# Write the runtime config.yaml and the Config class (config.py) that the
# application loads at startup (ports, paths, security and RTCM defaults).
echo "Creating configuration files..."

# Main YAML config
cat > $INST/config.yaml << EOF
# GNSS Caster Configuration
server:
  # host: kept for backward compatibility; prefer web_host/ntrip_host below.
  host: 0.0.0.0
  # Web backend binds locally only and is exposed via the nginx reverse proxy.
  web_host: 127.0.0.1
  # NTRIP server is a public correction stream and binds on all interfaces.
  ntrip_host: 0.0.0.0
  web_port: $INSTALL_WEB_PORT
  ntrip_port: $INSTALL_NTRIP_PORT
  debug: false

security:
  admin_default_user: admin
  bootstrap_admin_password_file: $BOOTSTRAP_ADMIN_PASSWORD_FILE
  # Secret is loaded from $SECRET_KEY_ENV_FILE via systemd EnvironmentFile.
  secret_key: ""
  session_timeout: 3600
  require_password_change: true
  max_login_attempts: 5
  login_lockout_time: 300

database:
  path: $INST/db.sqlite
  backup_path: $BACKUP_DIR
  backup_retention_days: 365

bluetooth:
  auto_reconnect: true
  reconnect_delay: 5
  connection_timeout: 30
  scan_timeout: 10
  use_dbus: true

ntrip:
  max_connections: 100
  connection_timeout: 30
  buffer_size: 1024

rtcm:
  version: "3.2"
  include_msm: true
  include_ssr: true
  enabled_groups:
    - "Reference"
    - "GPS"
    - "GLONASS"
    - "Galileo"
    - "BeiDou"
    - "QZSS"
    - "SBAS"
    - "Network RTK"
    - "MSM"
    - "SSR"
    - "Transformations"

logging:
  level: INFO
  max_size_mb: 10
  backup_count: 5

monitoring:
  health_check_interval: 60
  disk_threshold_percent: 85
  memory_threshold_percent: 90
EOF

# Python config
cat > $INST/config.py << EOF
import os
import yaml

CONFIG_PATH = os.path.join(os.path.dirname(__file__), 'config.yaml')

with open(CONFIG_PATH, 'r') as f:
    config = yaml.safe_load(f)

class Config:
    # Security
    SECRET_KEY = os.environ.get('SECRET_KEY') or config['security']['secret_key']
    BOOTSTRAP_ADMIN_PASSWORD_FILE = config['security'].get(
        'bootstrap_admin_password_file',
        '/opt/gnss-caster/instance/initial-admin-password'
    )
    SESSION_TIMEOUT = config['security']['session_timeout']
    MAX_LOGIN_ATTEMPTS = config['security']['max_login_attempts']
    LOGIN_LOCKOUT_TIME = config['security']['login_lockout_time']
    
    # Database
    SQLALCHEMY_DATABASE_URI = f"sqlite:///{config['database']['path']}"
    SQLALCHEMY_TRACK_MODIFICATIONS = False
    
    # Server
    HOST = config['server']['host']
    WEB_PORT = config['server']['web_port']
    NTRIP_PORT = config['server']['ntrip_port']
    DEBUG = config['server']['debug']
    
    # Bluetooth
    BT_AUTO_RECONNECT = config['bluetooth']['auto_reconnect']
    BT_RECONNECT_DELAY = config['bluetooth']['reconnect_delay']
    BT_SCAN_TIMEOUT = config['bluetooth']['scan_timeout']
    USE_DBUS = config['bluetooth']['use_dbus']
    
    # NTRIP
    NTRIP_MAX_CONNECTIONS = config['ntrip']['max_connections']
    NTRIP_TIMEOUT = config['ntrip']['connection_timeout']
    
    # RTCM
    RTCM_VERSION = config['rtcm']['version']
    RTCM_INCLUDE_MSM = config['rtcm']['include_msm']
    RTCM_INCLUDE_SSR = config['rtcm']['include_ssr']
    RTCM_ENABLED_GROUPS = config['rtcm']['enabled_groups']
    
    # Logging
    LOG_LEVEL = config['logging']['level']
    LOG_MAX_SIZE = config['logging']['max_size_mb'] * 1024 * 1024
    LOG_BACKUP_COUNT = config['logging']['backup_count']
    
    # Paths
    BACKUP_DIR = config['database']['backup_path']
    INSTANCE_DIR = os.path.dirname(__file__)
EOF

# ----------------- PYTHON VIRTUAL ENVIRONMENT -----------------
# Create the virtualenv and install the Python requirements: the Flask stack,
# waitress, SQLAlchemy/Alembic, dbus-next, and pyotp/qrcode for 2FA.
echo "Setting up Python virtual environment..."
if [ -d "$VENV" ]; then
  echo "Removing existing virtual environment for clean reinstall..."
  rm -rf "$VENV"
fi
python3 -m venv "$VENV"

source "$VENV/bin/activate"

# Tool versions are included in the reviewed, hashed requirements below.

