import time
import logging
import subprocess
import os
import select
import socket
import re
import math
from datetime import datetime, timezone
from collections import deque
from concurrent.futures import TimeoutError as FuturesTimeoutError
from types import SimpleNamespace
try:
    import serial
except Exception:
    serial = None
from dbus_next import BusType, Variant, DBusError
from dbus_next.aio import MessageBus
from dbus_next.service import ServiceInterface, method
from app.db.models import BaseStation, MountPoint, RTCMSetting, db, LogEntry, CommandLog, SystemSetting
from app.rtcm.registry import (
    build_receiver_rtcm_commands,
    get_default_enabled_rtcm_message_types,
    get_receiver_startup_message_types,
)
from app.rtcm.stream import stream_manager
