)

logger = logging.getLogger(__name__)

bcrypt = Bcrypt()

# In-memory registry of async privileged jobs (logrotate / backup cron).
# Lets the UI poll for real completion status instead of assuming success
# after a fire-and-forget thread was started (Fix #14).
_system_jobs = {}
_system_jobs_lock = threading.Lock()

def create_app():
    """Create and configure Flask application"""
    
    try:
        # Load configuration
        config_path = os.path.join(os.path.dirname(__file__), '../../instance/config.yaml')
        logger.debug(f"Loading config from: {config_path}")
        
        with open(config_path, 'r') as f:
            config = yaml.safe_load(f)

        server_config = config.get('server', {}) or {}
        security_config = config.get('security', {}) or {}
        logging_config = config.get('logging', {}) or {}

        def _normalize_log_level(raw_level, default_level='INFO'):
            normalized_level = str(raw_level or '').strip().upper()
            if normalized_level in ('CRITICAL', 'ERROR', 'WARNING', 'INFO', 'DEBUG'):
                return normalized_level
            return str(default_level or 'INFO').strip().upper()
        
        # Create Flask app
        app = Flask(__name__, 
                    template_folder='templates',
                    static_folder='static')
        app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1, x_host=1)
        app.config['MAX_CONTENT_LENGTH'] = 2 * 1024 * 1024

        @app.before_request
        def set_backup_upload_limit():
            if request.path == '/api/system/backups/upload':
                # Allow the file plus multipart headers; the file itself is
                # bounded separately while copying it to private storage.
                request.max_content_length = 129 * 1024 * 1024
        
        # Load config
        runtime_secret_key = str(os.environ.get('SECRET_KEY') or '').strip()
        if not runtime_secret_key:
            # Allow app startup outside systemd (installer migration/self-test)
            # by reading SECRET_KEY from the same EnvironmentFile used by unit.
            secret_env_path = '/etc/gnss-caster/secrets/secret.env'
            try:
                if os.path.isfile(secret_env_path):
                    with open(secret_env_path, 'r', encoding='utf-8', errors='ignore') as secret_file:
                        for raw_line in secret_file:
                            line = str(raw_line or '').strip()
                            if not line or line.startswith('#') or not line.startswith('SECRET_KEY='):
                                continue
                            runtime_secret_key = line.split('=', 1)[1].strip().strip('"').strip("'")
                            if runtime_secret_key:
                                break
            except Exception:
                runtime_secret_key = ''

        if not runtime_secret_key:
            runtime_secret_key = str(security_config.get('secret_key') or '').strip()

        if not runtime_secret_key:
            raise RuntimeError(
                'SECRET_KEY is not configured. '\
                'Set it via systemd EnvironmentFile=/etc/gnss-caster/secrets/secret.env'
            )

        app.config['SECRET_KEY'] = runtime_secret_key
        app.config['SQLALCHEMY_DATABASE_URI'] = f"sqlite:///{config['database']['path']}"
        app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
        try:
            app.config['SESSION_TIMEOUT'] = int(security_config.get('session_timeout', 3600) or 3600)
        except (TypeError, ValueError):
            app.config['SESSION_TIMEOUT'] = 3600
        app.config['DEBUG'] = bool(server_config.get('debug', False))
        legacy_host = str(server_config.get('host', '0.0.0.0') or '0.0.0.0').strip()
        # HOST is retained for backward compatibility, but web and NTRIP bind
        # hosts are resolved independently. The web backend defaults to
        # 127.0.0.1 so it is only reachable through the nginx reverse proxy,
        # while NTRIP defaults to 0.0.0.0 because it is a public stream.
        app.config['HOST'] = legacy_host
        app.config['WEB_HOST'] = str(
            server_config.get('web_host')
            or '127.0.0.1'
        ).strip() or '127.0.0.1'
        app.config['NTRIP_HOST'] = str(
            server_config.get('ntrip_host')
            or legacy_host
            or '0.0.0.0'
        ).strip() or '0.0.0.0'
        app.config['WEB_PORT'] = int(server_config.get('web_port', 8080) or 8080)
        app.config['NTRIP_PORT'] = int(server_config.get('ntrip_port', 2101) or 2101)
        app.config['LOG_LEVEL'] = _normalize_log_level(
            logging_config.get('level', 'DEBUG' if app.config['DEBUG'] else 'INFO')
        )
        app.config['BOOTSTRAP_ADMIN_PASSWORD_FILE'] = str(
            security_config.get(
                'bootstrap_admin_password_file',
                '/opt/gnss-caster/instance/initial-admin-password'
            ) or '/opt/gnss-caster/instance/initial-admin-password'
        ).strip()

        logging.getLogger().setLevel(
            getattr(logging, app.config['LOG_LEVEL'], logging.INFO)
        )
        
        logger.debug(f"Database URI: {app.config['SQLALCHEMY_DATABASE_URI']}")

        # SQLite tuning to avoid writer-vs-reader stalls that cause nginx to
        # reset upstream connections (browser sees "Failed to fetch") even
        # though the write actually committed.
        app.config['SQLALCHEMY_ENGINE_OPTIONS'] = {
            'pool_pre_ping': True,
            'pool_recycle': 300,
            'connect_args': {
                'timeout': 30,
                'check_same_thread': False,
            },
        }

        # Initialize extensions
        db.init_app(app)
        bcrypt.init_app(app)

        from sqlalchemy import event as _sa_event

        def _apply_sqlite_pragmas(dbapi_connection):
            try:
                cursor = dbapi_connection.cursor()
                cursor.execute('PRAGMA journal_mode=WAL')
                cursor.execute('PRAGMA synchronous=NORMAL')
                cursor.execute('PRAGMA busy_timeout=30000')
                cursor.execute('PRAGMA temp_store=MEMORY')
                cursor.execute('PRAGMA cache_size=-20000')
                cursor.close()
            except Exception as per_conn_error:
                logger.warning(f"SQLite PRAGMA setup failed: {per_conn_error}")

        try:
            with app.app_context():
                sqlite_engine = db.engine

                @_sa_event.listens_for(sqlite_engine, 'connect')
                def _sqlite_per_connection_pragmas(dbapi_connection, _connection_record):
                    _apply_sqlite_pragmas(dbapi_connection)

                # Apply PRAGMAs immediately to the initial pooled connection.
                raw_connection = sqlite_engine.raw_connection()
                try:
                    _apply_sqlite_pragmas(raw_connection)
                finally:
                    raw_connection.close()
        except Exception as sqlite_tune_error:
            logger.warning(f"SQLite tuning failed: {sqlite_tune_error}")
        
        # Login manager
        login_manager = LoginManager(app)
        login_manager.login_view = 'login'
        login_manager.login_message = 'Please log in to access this page.'
        
        @login_manager.user_loader
        def load_user(user_id):
            try:
                # Bare IDs from older releases are deliberately invalidated.
                admin_id, version = str(user_id).split(':', 1)
                user = Admin.query.get(int(admin_id))
                if user is not None and int(version) == int(user.session_version or 0):
                    return user
                return None
            except Exception as e:
                logger.error(f"Error loading user: {e}")
                return None

        def _should_show_password_change_notice(username_hint=''):
            """Show login warning only for accounts flagged to change password."""
            try:
                username_value = str(username_hint or '').strip()
                if username_value:
                    admin_user = Admin.query.filter_by(username=username_value).first()
                    return bool(
                        admin_user and getattr(admin_user, 'must_change_password', False)
                    )

                built_in_admin = Admin.query.order_by(Admin.id.asc()).first()
                if not built_in_admin:
                    return False

                return bool(getattr(built_in_admin, 'must_change_password', False))
            except Exception as notice_error:
                logger.warning(
                    f"Unable to evaluate password-change notice state: {notice_error}"
                )
                return False

        CSRF_UNSAFE_METHODS = {'POST', 'PUT', 'PATCH', 'DELETE'}

        def _get_or_create_csrf_token():
            csrf_token = str(session.get('_csrf_token') or '').strip()
            if not csrf_token:
                csrf_token = secrets.token_urlsafe(32)
                session['_csrf_token'] = csrf_token
            return csrf_token

        def _get_or_create_csp_nonce():
            nonce_value = str(getattr(g, '_csp_nonce', '') or '').strip()
            if not nonce_value:
                nonce_value = secrets.token_urlsafe(24)
                g._csp_nonce = nonce_value
            return nonce_value

        @app.context_processor
        def inject_csrf_token():
            return {
                'csrf_token': _get_or_create_csrf_token,
                'csp_nonce': _get_or_create_csp_nonce,
                'caster_version': __version__,
            }

        def _has_valid_csrf_token():
            expected_token = _get_or_create_csrf_token()
            token_candidates = [
                request.headers.get('X-CSRF-Token'),
                request.form.get('csrf_token'),
            ]

            for token_candidate in token_candidates:
                token_value = str(token_candidate or '').strip()
                if token_value and secrets.compare_digest(token_value, expected_token):
                    return True

            return False

        def _sanitize_audit_value(raw_value):
            text_value = str(raw_value or '').replace('\r', ' ').replace('\n', ' ').strip()
            return text_value[:160]

        def _summarize_audit_payload():
            payload = {}
            try:
                if request.is_json:
                    payload = request.get_json(silent=True) or {}
                elif request.form:
                    payload = request.form.to_dict(flat=True)
            except Exception:
                payload = {}

            if not isinstance(payload, dict):
                return ''

            sanitized_payload = {}
            for key, value in payload.items():
                key_text = str(key or '').strip()
                key_lower = key_text.lower()
                if any(marker in key_lower for marker in ('password', 'secret', 'token', 'pin', 'key')):
                    sanitized_payload[key_text] = '<redacted>'
                else:
                    sanitized_payload[key_text] = _sanitize_audit_value(value)

            return json.dumps(sanitized_payload, ensure_ascii=True, sort_keys=True)[:1000]

        def _normalize_dn_name(name_parts):
            if not name_parts:
                return ''

            normalized_parts = []
            for part_group in name_parts:
                for key, value in part_group:
                    normalized_parts.append(f'{key}={value}')
            return ', '.join(normalized_parts)

        def _extract_dn_value(name_parts, field_name):
            target_field = str(field_name or '').strip().lower()
            if not target_field:
                return ''

            for part_group in name_parts or []:
                for key, value in part_group:
                    if str(key).strip().lower() == target_field:
                        return str(value)
            return ''

        def _parse_cert_datetime(raw_value):
            text_value = str(raw_value or '').strip()
            if not text_value:
                return None

            try:
                parsed_value = parsedate_to_datetime(text_value)
                if parsed_value.tzinfo is None:
                    parsed_value = parsed_value.replace(tzinfo=timezone.utc)
                return parsed_value.astimezone(timezone.utc)
            except Exception:
                try:
                    parsed_value = datetime.strptime(text_value, '%b %d %H:%M:%S %Y %Z')
                    return parsed_value.replace(tzinfo=timezone.utc)
                except Exception:
                    return None

        def _decode_certificate_with_privileged_helper(cert_path):
            certificate_path = str(cert_path or '').strip()
            helper_result = _run_privileged_helper(
                ['certificate-info', certificate_path],
                timeout=30,
            )
            helper_output = str(helper_result.stdout or '').strip()
            if not helper_output:
                raise RuntimeError('privileged helper returned no certificate data')
            return json.loads(helper_output)

        def _load_certificate_info(cert_path):
            certificate_path = str(cert_path or '').strip()
            if not certificate_path:
                return {}

            temp_cert_path = ''
            try:
                try:
                    if not os.path.isfile(certificate_path):
                        raise FileNotFoundError(
                            'certificate file is not readable by the service user'
                        )

                    with open(certificate_path, 'r', encoding='utf-8', errors='ignore') as cert_file:
                        pem_text = cert_file.read()

                    begin_marker = '-----BEGIN CERTIFICATE-----'
                    end_marker = '-----END CERTIFICATE-----'
                    if pem_text.count(begin_marker) > 1 and end_marker in pem_text:
                        first_certificate = pem_text.split(end_marker, 1)[0] + end_marker + '\n'
                        with tempfile.NamedTemporaryFile(
                            mode='w',
                            encoding='utf-8',
                            delete=False
                        ) as temp_cert_file:
                            temp_cert_file.write(first_certificate)
                            temp_cert_path = temp_cert_file.name
                        decode_path = temp_cert_path
                    else:
                        decode_path = certificate_path

                    decoded = ssl._ssl._test_decode_cert(decode_path)
                except Exception as direct_decode_error:
                    try:
                        decoded = _decode_certificate_with_privileged_helper(certificate_path)
                    except Exception as helper_decode_error:
                        raise RuntimeError(
                            f'direct certificate decode failed: {direct_decode_error}; '
                            f'privileged helper decode failed: {helper_decode_error}'
                        ) from helper_decode_error

                subject = decoded.get('subject', ())
                issuer = decoded.get('issuer', ())
                san_entries = decoded.get('subjectAltName', ()) or ()
                serial_number = str(decoded.get('serialNumber', '') or '').strip()

                not_before_dt = _parse_cert_datetime(decoded.get('notBefore'))
                not_after_dt = _parse_cert_datetime(decoded.get('notAfter'))
                now_dt = datetime.now(timezone.utc)

                days_remaining = None
                if not_after_dt is not None:
                    remaining_seconds = (not_after_dt - now_dt).total_seconds()
                    days_remaining = int(remaining_seconds // 86400)

                common_name = _extract_dn_value(subject, 'commonName')
                organization_name = _extract_dn_value(subject, 'organizationName')

                san_values = []
                for san_type, san_value in san_entries:
                    san_values.append(f'{san_type}:{san_value}')

                return {
                    'subject': _normalize_dn_name(subject),
                    'subject_common_name': common_name,
                    'subject_organization': organization_name,
                    'issuer': _normalize_dn_name(issuer),
                    'issuer_common_name': _extract_dn_value(issuer, 'commonName'),
                    'serial_number': serial_number,
                    'subject_alt_names': san_values,
                    'not_before': not_before_dt.isoformat() if not_before_dt else '',
                    'not_after': not_after_dt.isoformat() if not_after_dt else '',
                    'days_remaining': days_remaining,
                    'expired': bool(not_after_dt and now_dt > not_after_dt),
                    'valid_now': bool(
                        not_before_dt and not_after_dt and not_before_dt <= now_dt <= not_after_dt
                    ),
                }
            except Exception as cert_error:
                logger.warning(f'Unable to decode TLS certificate "{certificate_path}": {cert_error}')
                return {'error': str(cert_error)}
            finally:
                if temp_cert_path:
                    try:
                        os.unlink(temp_cert_path)
                    except Exception:
                        pass

        def _read_current_tls_configuration():
            nginx_site_path = '/etc/nginx/sites-available/gnss-caster'
            tls_info = {
                'nginx_site_path': nginx_site_path,
                'nginx_site_present': os.path.isfile(nginx_site_path),
                'https_enabled': False,
                'tls_mode': 'none',
                'tls_mode_label': 'HTTP only',
                'server_name': '',
                'cert_path': '',
                'key_path': '',
                'certificate_present': False,
                'certificate_info': {},
            }

            if not tls_info['nginx_site_present']:
                return tls_info

            try:
                with open(nginx_site_path, 'r', encoding='utf-8', errors='ignore') as nginx_file:
                    nginx_config = nginx_file.read()
            except Exception as nginx_read_error:
                tls_info['error'] = str(nginx_read_error)
                return tls_info

            tls_info['https_enabled'] = bool(re.search(r'listen\s+443\s+ssl', nginx_config))

            server_names = re.findall(r'^\s*server_name\s+([^;]+);', nginx_config, flags=re.MULTILINE)
            if server_names:
                tls_info['server_name'] = str(server_names[-1]).strip()

            cert_match = re.search(r'^\s*ssl_certificate\s+([^;]+);', nginx_config, flags=re.MULTILINE)
            key_match = re.search(r'^\s*ssl_certificate_key\s+([^;]+);', nginx_config, flags=re.MULTILINE)

            if cert_match:
                tls_info['cert_path'] = str(cert_match.group(1)).strip()
            if key_match:
                tls_info['key_path'] = str(key_match.group(1)).strip()

            certificate_path = tls_info['cert_path']
            if tls_info['https_enabled'] and certificate_path:
                if certificate_path == '/etc/ssl/certs/gnss-caster.crt':
                    tls_info['tls_mode'] = 'selfsigned'
                    tls_info['tls_mode_label'] = 'Self-signed certificate'
                elif '/etc/letsencrypt/live/' in certificate_path:
                    tls_info['tls_mode'] = 'letsencrypt'
                    tls_info['tls_mode_label'] = "Let's Encrypt"
                else:
                    tls_info['tls_mode'] = 'custom'
                    tls_info['tls_mode_label'] = 'Custom certificate'

            if certificate_path:
                certificate_info = _load_certificate_info(certificate_path)
                tls_info['certificate_info'] = certificate_info
                tls_info['certificate_present'] = bool(
                    certificate_info and not certificate_info.get('error')
                )

            return tls_info

        LOGIN_IP_WINDOW_SECONDS = 600
        LOGIN_IP_BLOCK_SECONDS = 600
        LOGIN_IP_MAX_FAILURES = 10
        login_ip_failures = {}

        def _get_client_ip():
            # ProxyFix(x_for=1) already resolves the single trusted local nginx
            # hop and places the real client address in request.remote_addr.
            # Do not trust the first raw X-Forwarded-For value here: a client can
            # prepend a spoofed address and bypass per-IP rate limiting/auditing.
            remote_ip = str(request.remote_addr or '').strip()
            real_ip = str(request.headers.get('X-Real-IP', '') or '').strip()
            return (remote_ip or real_ip or 'unknown')[:64]

        def _prune_login_ip_failures(now_ts=None):
            current_ts = int(now_ts or time.time())
            stale_ips = []

            for ip_address, entry in login_ip_failures.items():
                recent_failures = [
                    ts for ts in entry.get('failures', [])
                    if (current_ts - int(ts)) <= LOGIN_IP_WINDOW_SECONDS
                ]
                blocked_until = int(entry.get('blocked_until', 0) or 0)
                if blocked_until <= current_ts:
                    blocked_until = 0

                if not recent_failures and blocked_until == 0:
                    stale_ips.append(ip_address)
                    continue

                entry['failures'] = recent_failures
                entry['blocked_until'] = blocked_until

            for ip_address in stale_ips:
                login_ip_failures.pop(ip_address, None)

        def _get_login_ip_block_seconds(ip_address):
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return 0

            current_ts = int(time.time())
            _prune_login_ip_failures(current_ts)
            entry = login_ip_failures.get(normalized_ip)
            if not entry:
                return 0

            blocked_until = int(entry.get('blocked_until', 0) or 0)
            if blocked_until <= current_ts:
                return 0

            return max(0, blocked_until - current_ts)

        def _record_login_ip_failure(ip_address):
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return 0

            current_ts = int(time.time())
            _prune_login_ip_failures(current_ts)
            entry = login_ip_failures.setdefault(
                normalized_ip,
                {'failures': [], 'blocked_until': 0}
            )
            entry['failures'].append(current_ts)
            entry['failures'] = [
                ts for ts in entry.get('failures', [])
                if (current_ts - int(ts)) <= LOGIN_IP_WINDOW_SECONDS
            ]

            if len(entry['failures']) >= LOGIN_IP_MAX_FAILURES:
                entry['blocked_until'] = current_ts + LOGIN_IP_BLOCK_SECONDS

            return _get_login_ip_block_seconds(normalized_ip)

        def _clear_login_ip_failures(ip_address):
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return
            login_ip_failures.pop(normalized_ip, None)

        def _truncate_command_output(raw_text, max_chars=6000):
            text_value = str(raw_text or '').strip()
            if not text_value:
                return ''
            if len(text_value) <= max_chars:
                return text_value
            return text_value[:max_chars] + '\n...[truncated]...'

        SYSTEM_COMMAND_PATH = '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'

        def _build_subprocess_env():
            env = os.environ.copy()
            current_path = str(env.get('PATH') or '').strip()
            env['PATH'] = (
                f'{current_path}:{SYSTEM_COMMAND_PATH}'
                if current_path else
                SYSTEM_COMMAND_PATH
            )
            return env

        PRIVILEGED_HELPER_PATH = '/opt/gnss-caster/gnss-caster-privileged-helper.sh'
        ADMIN_PASSWORD_MIN_LENGTH = 12
        ROVER_PASSWORD_MIN_LENGTH = 12
        VALID_ADMIN_ROLES = {'admin', 'operator', 'viewer'}

        def _run_privileged_helper(helper_args, timeout=30):
            if not os.path.isfile(PRIVILEGED_HELPER_PATH):
                raise FileNotFoundError(f'Privileged helper not found: {PRIVILEGED_HELPER_PATH}')

            command = ['sudo', '-n', PRIVILEGED_HELPER_PATH, *[str(arg) for arg in helper_args]]
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=timeout,
                env=_build_subprocess_env()
            )
            if result.returncode != 0:
                raise RuntimeError(
                    _truncate_command_output(result.stderr or result.stdout)
                    or 'Privileged helper command failed'
                )

            return result

        def _normalize_admin_role(raw_role, default_role='operator'):
            normalized_role = str(raw_role or default_role).strip().lower()
            if normalized_role not in VALID_ADMIN_ROLES:
                raise ValueError('role must be admin, operator, or viewer')
            return normalized_role

        def _current_admin_role():
            try:
                role_value = str(getattr(current_user, 'role', '') or '').strip().lower()
                if role_value in VALID_ADMIN_ROLES:
                    return role_value

                first_admin = Admin.query.order_by(Admin.id.asc()).first()
                if first_admin and int(first_admin.id) == int(current_user.id):
                    return 'admin'
            except Exception:
                pass

            return 'viewer'

        def _require_admin_role():
            if _current_admin_role() == 'admin':
                return None
            return jsonify({'error': 'Administrator role required'}), 403

        def _require_operator_role():
            if _current_admin_role() in ('admin', 'operator'):
                return None
            return jsonify({'error': 'Operator or administrator role required'}), 403

        # ── API token authentication (Fix #20) ──────────────────────────────
        def _hash_token(raw_token):
            return hashlib.sha256(str(raw_token or '').encode('utf-8')).hexdigest()

        def _authenticate_api_token():
            """Validate a bearer/API-key token from the request headers.

            Accepts either:
              Authorization: Bearer <token>
              X-API-Key: <token>
            Returns the ApiToken row on success, or None.
            Updates last_used on success.
            """
            raw = None
            auth = request.headers.get('Authorization', '')
            if auth.lower().startswith('bearer '):
                raw = auth[7:].strip()
            if not raw:
                raw = request.headers.get('X-API-Key', '').strip()
            if not raw:
                return None

            token_row = ApiToken.query.filter_by(
                token_hash=_hash_token(raw), is_active=True
            ).first()
            if not token_row:
                return None
            if token_row.is_expired():
                return None

            token_row.last_used = int(time.time())
            try:
                db.session.commit()
            except Exception:
                db.session.rollback()
            return token_row

        def api_token_or_login_required(view_func):
            """Allow access via a valid API token OR an authenticated session.

            Read-scoped tokens are limited to safe HTTP methods (GET/HEAD).
            """
            @wraps(view_func)
            def wrapped(*args, **kwargs):
                # Session auth takes precedence (browser use).
                if getattr(current_user, 'is_authenticated', False):
                    return view_func(*args, **kwargs)

                token_row = _authenticate_api_token()
                if token_row:
                    if token_row.scope == 'read' and request.method not in ('GET', 'HEAD'):
                        return jsonify({'error': 'This API token is read-only'}), 403
                    g.api_token = token_row
                    return view_func(*args, **kwargs)

                return jsonify({'error': 'Authentication required'}), 401
            return wrapped

        def _validate_password_strength(password, username='', min_length=12, label='Password'):
            password_text = str(password or '')
            username_text = str(username or '').strip().lower()

            if len(password_text) < min_length:
                raise ValueError(f'{label} must be at least {min_length} characters long')

            lowered_password = password_text.strip().lower()
            weak_values = {
                'password',
                'admin',
                'administrator',
                'gnsscaster',
                'gnss-caster',
                '123456',
                '12345678',
                '123456789',
                'qwerty',
                'letmein',
            }
            if lowered_password in weak_values:
                raise ValueError(f'{label} is too common')

            if username_text and lowered_password == username_text:
                raise ValueError(f'{label} must be different from the username')

            return password_text

        def _is_bcrypt_hash(raw_password):
            return str(raw_password or '').startswith('$2')

        def _get_bootstrap_admin_password_file():
            configured_path = str(
                os.environ.get('GNSS_CASTER_BOOTSTRAP_PASSWORD_FILE')
                or app.config.get('BOOTSTRAP_ADMIN_PASSWORD_FILE')
                or '/opt/gnss-caster/instance/initial-admin-password'
            ).strip()
            return configured_path or '/opt/gnss-caster/instance/initial-admin-password'

        def _remove_bootstrap_admin_password_file(username=None):
            password_file_path = _get_bootstrap_admin_password_file()
            target_username = str(username or '').strip()
            try:
                if not os.path.isfile(password_file_path):
                    return False

                if target_username:
                    file_username = ''
                    with open(password_file_path, 'r', encoding='utf-8') as password_file:
                        for raw_line in password_file:
                            line = str(raw_line or '').strip()
                            if line.startswith('username='):
                                file_username = line.split('=', 1)[1].strip()
                                break

                    if file_username and file_username != target_username:
                        return False

                os.remove(password_file_path)
                logger.info(f"Removed bootstrap admin password file {password_file_path}")
                return True
            except Exception as cleanup_error:
                logger.warning(
                    f"Unable to remove bootstrap admin password file "
                    f"{password_file_path}: {cleanup_error}"
                )
                return False

        def _write_bootstrap_admin_password_file(username, password, reason):
            password_file_path = _get_bootstrap_admin_password_file()
            password_dir = os.path.dirname(password_file_path)
            if password_dir:
                os.makedirs(password_dir, exist_ok=True)

            file_contents = (
                "# GNSS Caster bootstrap admin credentials\n"
                f"username={username}\n"
                f"password={password}\n"
                f"reason={reason}\n"
                f"generated_at={int(time.time())}\n"
            )

            write_private_text(password_file_path, file_contents)
            return password_file_path

        def _generate_bootstrap_password():
            return secrets.token_urlsafe(18)

        def _built_in_admin_uses_insecure_default(admin_user, default_username):
            if not admin_user:
                return False

            stored_password = str(getattr(admin_user, 'password', '') or '')
            normalized_default_username = str(default_username or '').strip()
            if not stored_password or not normalized_default_username:
                return False

            if stored_password == normalized_default_username:
                return True

            if not _is_bcrypt_hash(stored_password):
                return False

            try:
                return bcrypt.check_password_hash(
                    stored_password,
                    normalized_default_username
                )
            except Exception:
                return False

        def _ensure_built_in_admin(default_username):
            normalized_default_username = str(default_username or '').strip()
            if not normalized_default_username:
                raise RuntimeError('security.admin_default_user must not be empty')

            built_in_admin = Admin.query.filter_by(
                username=normalized_default_username
            ).first()

            if not built_in_admin:
                bootstrap_password = _generate_bootstrap_password()
                password_file_path = _write_bootstrap_admin_password_file(
                    normalized_default_username,
                    bootstrap_password,
                    'created',
                )

                try:
                    built_in_admin = Admin(
                        username=normalized_default_username,
                        password=bcrypt.generate_password_hash(bootstrap_password).decode(),
                        role='admin',
                        email='admin@gnss-caster.local',
                        must_change_password=True
                    )
                    db.session.add(built_in_admin)
                    db.session.commit()
                except Exception:
                    try:
                        os.remove(password_file_path)
                    except Exception:
                        pass
                    raise

                logger.warning(
                    f"Default admin user created. Bootstrap credentials written to "
                    f"{password_file_path}"
                )
                return

            if str(getattr(built_in_admin, 'role', '') or '').strip().lower() != 'admin':
                built_in_admin.role = 'admin'
                built_in_admin.updated_at = int(time.time())
                db.session.commit()

            if not _built_in_admin_uses_insecure_default(
                built_in_admin,
                normalized_default_username
            ):
                return

            bootstrap_password = _generate_bootstrap_password()
            password_file_path = _write_bootstrap_admin_password_file(
                normalized_default_username,
                bootstrap_password,
                'rotated',
            )

            try:
                built_in_admin.set_password_hash(bcrypt.generate_password_hash(
                    bootstrap_password
                ).decode())
                built_in_admin.must_change_password = True
                built_in_admin.updated_at = int(time.time())
                db.session.commit()
            except Exception:
                try:
                    os.remove(password_file_path)
                except Exception:
                    pass
                raise

            logger.warning(
                f"Built-in admin credentials were still using the known default and "
                f"have been rotated. New bootstrap credentials written to "
                f"{password_file_path}"
            )

        def _migrate_legacy_rover_passwords():
            migrated_count = 0

            for rover in Rover.query.all():
                current_password = str(getattr(rover, 'password', '') or '')
                if not current_password or _is_bcrypt_hash(current_password):
                    continue

                rover.password = bcrypt.generate_password_hash(current_password).decode()
                rover.updated_at = int(time.time())
                migrated_count += 1

            if migrated_count <= 0:
                return 0

            db.session.commit()
            logger.warning(
                f"Migrated {migrated_count} legacy rover password(s) from plaintext to bcrypt"
            )
            return migrated_count

        def _write_logrotate_config(rotation_days):
            rotate_days = max(1, min(int(rotation_days), 3650))
            logrotate_path = '/etc/logrotate.d/gnss-caster'
            _run_privileged_helper(['write-logrotate', str(rotate_days)], timeout=30)
            return logrotate_path

        def _backup_interval_to_cron_expression(interval_seconds):
            normalized_seconds = max(3600, int(interval_seconds))
            interval_minutes = max(60, int(round(normalized_seconds / 60.0)))

            if interval_minutes < 60:
                return f'*/{interval_minutes} * * * *'

            if interval_minutes < 1440 and interval_minutes % 60 == 0:
                interval_hours = max(1, interval_minutes // 60)
                if interval_hours == 24:
                    return '0 2 * * *'
                return f'0 */{interval_hours} * * *'

            if interval_minutes % 1440 == 0:
                interval_days = max(1, interval_minutes // 1440)
                if interval_days <= 28:
                    return f'0 2 */{interval_days} * *'

            return '0 2 * * *'

        def _write_backup_cron(auto_backup_enabled, interval_seconds):
            if not bool(auto_backup_enabled):
                _run_privileged_helper(['write-backup-cron', '0', str(interval_seconds)], timeout=30)
                return ''

            cron_expression = _backup_interval_to_cron_expression(interval_seconds)
            _run_privileged_helper(
                ['write-backup-cron', '1', str(interval_seconds)],
                timeout=30
            )
            return cron_expression

        def _get_system_setting_value(key, default_value=''):
            setting = SystemSetting.query.filter_by(key=str(key)).first()
            if not setting or setting.value is None:
                return default_value
            return setting.value

        def _build_logs_summary():
            now_ts = int(time.time())
            since_ts = now_ts - 86400
            total_logs = LogEntry.query.count()
            recent_logs = LogEntry.query.filter(LogEntry.timestamp >= since_ts)

            last_log = LogEntry.query.order_by(LogEntry.timestamp.desc()).first()
            module_rows = db.session.query(LogEntry.module).distinct().all()
            modules = sorted(
                str(row[0]).strip() for row in module_rows
                if row and row[0]
            )

            return {
                'total_logs': total_logs,
                'recent_24h': recent_logs.count(),
                'info_24h': recent_logs.filter(LogEntry.level == 'INFO').count(),
                'warning_24h': recent_logs.filter(LogEntry.level == 'WARNING').count(),
                'error_24h': recent_logs.filter(LogEntry.level == 'ERROR').count(),
                'modules': modules,
                'last_log_at': int(last_log.timestamp) if last_log else 0,
            }

        def _list_backup_files(limit=20):
            backup_dir = '/opt/gnss-caster/backups'
            items = []

            if os.path.isdir(backup_dir):
                for entry_name in os.listdir(backup_dir):
                    if (
                        not entry_name.startswith('backup_')
                        or not entry_name.endswith(('.tar.gz', '.tar.gz.enc'))
                    ):
                        continue

                    entry_path = os.path.join(backup_dir, entry_name)
                    if not os.path.isfile(entry_path):
                        continue

                    try:
                        stat_info = os.stat(entry_path)
                    except Exception:
                        continue

                    items.append({
                        'name': entry_name,
                        'path': entry_path,
                        'size_bytes': int(stat_info.st_size),
                        'modified_at': int(stat_info.st_mtime),
                    })

            items.sort(key=lambda item: item.get('modified_at', 0), reverse=True)
            trimmed_items = items[:max(1, min(int(limit), 100))]

            return {
                'backup_dir': backup_dir,
                'items': trimmed_items,
                'count': len(items),
                'total_size_bytes': sum(int(item.get('size_bytes', 0) or 0) for item in items),
                'latest': trimmed_items[0] if trimmed_items else None,
                'backup_retention_days': int(_get_system_setting_value('data_retention', '365') or 365),
                'log_dir': '/var/log/gnss-caster',
                'log_summary': _build_logs_summary(),
            }

        def _store_uploaded_backup(upload, backup_dir='/opt/gnss-caster/backups', max_bytes=128 * 1024 * 1024):
            original = str(getattr(upload, 'filename', '') or '')
            if not original or '/' in original or '\\' in original or any(ord(c) < 32 for c in original):
                raise ValueError('Choose a backup file without a path in its name')
            suffix = next((s for s in ('.tar.gz.enc', '.tar.gz') if original.lower().endswith(s)), None)
            if not suffix:
                raise ValueError('Supported files: .tar.gz and .tar.gz.enc')
            os.makedirs(backup_dir, exist_ok=True)
            if shutil.disk_usage(backup_dir).free < max_bytes + 64 * 1024 * 1024:
                raise ValueError('Not enough free space to upload a backup')
            stem = re.sub(r'[^A-Za-z0-9_.-]', '_', original[:-len(suffix)])[:80].strip('.') or 'uploaded'
            if not stem.startswith('backup_'):
                stem = 'backup_' + stem
            name = f'{stem}_upload_{secrets.token_hex(8)}{suffix}'
            target = os.path.join(backup_dir, name)
            fd, temporary = tempfile.mkstemp(prefix='.upload-', dir=backup_dir)
            size = 0
            try:
                with os.fdopen(fd, 'wb') as out:
                    while True:
                        chunk = upload.stream.read(min(1024 * 1024, max_bytes + 1 - size))
                        if not chunk:
                            break
                        size += len(chunk)
                        if size > max_bytes:
                            raise ValueError('Backup exceeds the 128 MiB upload limit')
                        out.write(chunk)
                    out.flush()
                    os.fsync(out.fileno())
                with open(temporary, 'rb') as inp:
                    header = inp.read(16)
                if suffix == '.tar.gz.enc':
                    valid = len(header) == 16 and header.startswith(b'Salted__') and size >= 32
                else:
                    valid = header.startswith(b'\x1f\x8b\x08') and size >= 18
                if not valid:
                    raise ValueError('The file does not have a supported backup format')
                # Publish only the completed file, without overwriting another
                # archive even in the unlikely event of a name collision.
                os.link(temporary, target)
                return {'filename': name, 'original_filename': original, 'size_bytes': size,
                        'encrypted': suffix.endswith('.enc')}
            finally:
                os.unlink(temporary)

        def _resolve_backup_archive_path(filename):
            safe_name = os.path.basename(str(filename or '').strip())
            if (
                not safe_name
                or not safe_name.startswith('backup_')
                or not safe_name.endswith(('.tar.gz', '.tar.gz.enc'))
            ):
                raise ValueError('Invalid backup filename')

            backup_path = os.path.join('/opt/gnss-caster/backups', safe_name)
            if not os.path.isfile(backup_path):
                raise FileNotFoundError('Backup file not found')

            return safe_name, backup_path

        def _delete_backup_archive(filename):
            safe_name, backup_path = _resolve_backup_archive_path(filename)
            os.remove(backup_path)
            return {
                'filename': safe_name,
                'path': backup_path,
            }

        def _is_valid_system_job_name(unit_name):
            normalized_name = str(unit_name or '').strip().lower()
            return bool(re.fullmatch(r'gnss-caster-[a-z0-9-]+\.service', normalized_name))

        def _parse_systemd_show_output(raw_output):
            properties = {}
            for raw_line in str(raw_output or '').splitlines():
                if '=' not in raw_line:
                    continue

                key, value = raw_line.split('=', 1)
                properties[str(key or '').strip()] = str(value or '').strip()

            return properties

        def _schedule_system_job(job_type, command_args):
            normalized_job_type = re.sub(r'[^a-z0-9-]+', '-', str(job_type or 'job').strip().lower()) or 'job'
            if normalized_job_type not in ('backup', 'restore'):
                raise ValueError('Unsupported maintenance job type')

            unit_name = (
                f'gnss-caster-{normalized_job_type}-'
                f'{int(time.time())}-{secrets.token_hex(2)}.service'
            )

            helper_args = ['systemd-job', normalized_job_type, unit_name]
            if normalized_job_type == 'restore':
                arguments = list(command_args)
                if len(arguments) < 2:
                    raise ValueError('Restore job requires a backup filename')
                helper_args.append(str(arguments[1]))
                if len(arguments) > 2 and arguments[2]:
                    helper_args.append(str(arguments[2]))

            result = _run_privileged_helper(helper_args, timeout=30)

            return {
                'unit_name': unit_name,
                'job_type': normalized_job_type,
                'status_url': f'/api/system/jobs/{unit_name}',
                'stdout': _truncate_command_output(result.stdout),
                'stderr': _truncate_command_output(result.stderr),
            }

        def _get_system_job_status(unit_name):
            normalized_unit_name = str(unit_name or '').strip()
            if not _is_valid_system_job_name(normalized_unit_name):
                raise ValueError('Invalid system job unit name')

            subprocess_env = _build_subprocess_env()
            if not shutil.which('systemctl', path=subprocess_env.get('PATH', SYSTEM_COMMAND_PATH)):
                raise FileNotFoundError('systemctl is not available on this system')

            result = subprocess.run(
                [
                    'systemctl',
                    'show',
                    normalized_unit_name,
                    '--no-pager',
                    '--property=Id,LoadState,ActiveState,SubState,Result,ExecMainStatus,ExecMainCode,Description',
                ],
                capture_output=True,
                text=True,
                timeout=30,
                env=subprocess_env
            )

            combined_output = _truncate_command_output(result.stderr or result.stdout)
            if result.returncode != 0:
                lower_output = f'{result.stdout}\n{result.stderr}'.lower()
                if (
                    'could not be found' in lower_output
                    or 'not-found' in lower_output
                    or 'not loaded' in lower_output
                ):
                    return {
                        'unit_name': normalized_unit_name,
                        'status': 'not_found',
                        'message': 'Systemd unit not found',
                        'load_state': 'not-found',
                        'active_state': 'inactive',
                        'sub_state': 'dead',
                        'result': '',
                        'exec_main_status': '',
                        'exec_main_code': '',
                        'is_finished': True,
                    }

                raise RuntimeError(combined_output or 'Unable to query maintenance job status')

            properties = _parse_systemd_show_output(result.stdout)
            load_state = str(properties.get('LoadState', '') or '').strip().lower()
            active_state = str(properties.get('ActiveState', '') or '').strip().lower()
            sub_state = str(properties.get('SubState', '') or '').strip().lower()
            result_value = str(properties.get('Result', '') or '').strip().lower()
            exec_main_status = str(properties.get('ExecMainStatus', '') or '').strip()
            exec_main_code = str(properties.get('ExecMainCode', '') or '').strip()

            if load_state == 'not-found':
                status = 'not_found'
                message = 'Systemd unit not found'
            elif active_state in ('activating', 'reloading', 'deactivating'):
                status = 'running'
                message = 'Maintenance job is still running'
            elif active_state == 'active' and sub_state != 'exited':
                status = 'running'
                message = 'Maintenance job is still running'
            elif active_state == 'active' and sub_state == 'exited':
                if result_value not in ('', 'success') or exec_main_status not in ('', '0'):
                    status = 'failed'
                    message = 'Maintenance job finished with errors'
                else:
                    status = 'completed'
                    message = 'Maintenance job completed successfully'
            elif active_state == 'inactive':
                if result_value not in ('', 'success') or exec_main_status not in ('', '0'):
                    status = 'failed'
                    message = 'Maintenance job finished with errors'
                else:
                    status = 'completed'
                    message = 'Maintenance job completed successfully'
            elif active_state == 'failed' or result_value not in ('', 'success'):
                status = 'failed'
                message = 'Maintenance job finished with errors'
            else:
                status = 'unknown'
                message = 'Maintenance job state is unknown'

            return {
                'unit_name': normalized_unit_name,
                'description': str(properties.get('Description', '') or '').strip(),
                'status': status,
                'message': message,
                'load_state': load_state,
                'active_state': active_state,
                'sub_state': sub_state,
                'result': result_value,
                'exec_main_status': exec_main_status,
                'exec_main_code': exec_main_code,
                'is_finished': status in ('completed', 'failed', 'not_found'),
            }

        def _schedule_backup_script():
            backup_script_path = '/opt/gnss-caster/backup.sh'
            if not os.path.isfile(backup_script_path):
                raise FileNotFoundError(f'Backup script not found: {backup_script_path}')

            scheduled_job = _schedule_system_job('backup', [backup_script_path])
            scheduled_job['script'] = backup_script_path
            return scheduled_job

        def _schedule_restore_script(filename, passphrase=''):
            restore_script_path = '/opt/gnss-caster/restore.sh'
            if not os.path.isfile(restore_script_path):
                raise FileNotFoundError(f'Restore script not found: {restore_script_path}')

            safe_name, _ = _resolve_backup_archive_path(filename)

            # Hand the passphrase over in a private file rather than on the
            # command line, which any local user could read from /proc. The
            # restore script deletes it as soon as it has been read.
            passphrase_path = ''
            passphrase_created = False
            try:
                if passphrase:
                    passphrase_path = f'/run/gnss-caster/restore-{secrets.token_hex(8)}.key'
                    descriptor = os.open(
                        passphrase_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600
                    )
                    passphrase_created = True
                    with os.fdopen(descriptor, 'w', encoding='utf-8') as handle:
                        handle.write(str(passphrase))

                scheduled_job = _schedule_system_job(
                    'restore', [restore_script_path, safe_name, passphrase_path]
                )
            except Exception:
                if passphrase_created:
                    try:
                        os.unlink(passphrase_path)
                    except FileNotFoundError:
                        pass
                raise
            scheduled_job['script'] = restore_script_path
            scheduled_job['filename'] = safe_name
            return scheduled_job

        def _renew_letsencrypt_certificates(force=False):
            tls_info = _read_current_tls_configuration()
            if str(tls_info.get('tls_mode', '')).strip().lower() != 'letsencrypt':
                raise ValueError("Active TLS mode is not Let's Encrypt")

            result = _run_privileged_helper(
                ['certbot-renew', '1' if bool(force) else '0'],
                timeout=1800
            )
            command = ['certbot', 'renew', '--non-interactive']
            if bool(force):
                command.append('--force-renewal')

            return {
                'command': ' '.join(command),
                'stdout': _truncate_command_output(result.stdout),
                'stderr': _truncate_command_output(result.stderr),
                'nginx_reloaded': True,
                'nginx_output': 'nginx reloaded by privileged helper',
            }

        def _schedule_power_action(action):
            normalized_action = str(action or '').strip().lower()
            if normalized_action not in ('reboot', 'shutdown'):
                raise ValueError('Unsupported power action')

            delay_seconds = 5
            unit_name = (
                f'gnss-caster-power-{normalized_action}-'
                f'{int(time.time())}-{secrets.token_hex(2)}.service'
            )

            result = _run_privileged_helper(
                ['power', normalized_action, unit_name, str(delay_seconds)],
                timeout=30
            )

            return {
                'action': normalized_action,
                'unit_name': unit_name,
                'delay_seconds': delay_seconds,
                'stdout': _truncate_command_output(result.stdout),
                'stderr': _truncate_command_output(result.stderr),
                'scheduler': 'systemd-run',
            }

        active_tls_bootstrap = _read_current_tls_configuration()
        app.config['SESSION_COOKIE_HTTPONLY'] = True
        app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'
        app.config['REMEMBER_COOKIE_HTTPONLY'] = True
        app.config['SESSION_COOKIE_SECURE'] = bool(active_tls_bootstrap.get('https_enabled'))
        app.config['REMEMBER_COOKIE_SECURE'] = bool(active_tls_bootstrap.get('https_enabled'))

        @app.after_request
        def apply_security_headers(response):
            csp_nonce_value = _get_or_create_csp_nonce()
            response.headers['X-Frame-Options'] = 'DENY'
            response.headers['X-Content-Type-Options'] = 'nosniff'
            response.headers['Referrer-Policy'] = 'same-origin'
            response.headers['Permissions-Policy'] = 'geolocation=(), microphone=(), camera=()'
            response.headers['Content-Security-Policy'] = (
                "default-src 'self'; "
                "img-src 'self' data:; "
                "style-src 'self' 'unsafe-inline'; "
                # React handlers are bundled; the bootstrap uses a request nonce.
                f"script-src 'self' 'nonce-{csp_nonce_value}'; "
                "script-src-attr 'none'; "
                "font-src 'self' data:; "
                "connect-src 'self'; "
                # Safe hardening that does not depend on the inline-handler
                # migration: no plugins, no <base> hijacking of relative URLs,
                # and forms may only post back to this origin.
                "object-src 'none'; "
                "base-uri 'self'; "
                "form-action 'self'; "
                "frame-ancestors 'none'"
            )
            # Strict target policy for CSP migration (report-only to avoid
            # breaking existing inline handlers/templates during transition).
            response.headers['Content-Security-Policy-Report-Only'] = (
                "default-src 'self'; "
                "img-src 'self' data:; "
                f"style-src 'self' 'nonce-{csp_nonce_value}'; "
                "style-src-attr 'unsafe-inline'; "
                f"script-src 'self' 'nonce-{csp_nonce_value}'; "
                "script-src-attr 'none'; "
                "font-src 'self' data:; "
                "connect-src 'self'; "
                "object-src 'none'; "
                "base-uri 'self'; "
                "form-action 'self'; "
                "frame-ancestors 'none'"
            )

            if request.is_secure or str(request.headers.get('X-Forwarded-Proto', '')).lower() == 'https':
                response.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'

            return response

        @app.before_request
        def enforce_csrf_protection():
            # Session inactivity timeout (applies to authenticated sessions).
            if current_user.is_authenticated:
                now_ts = int(time.time())
                session_timeout = int(app.config.get('SESSION_TIMEOUT', 3600) or 3600)
                if session_timeout < 60:
                    session_timeout = 60

                last_active = session.get('_last_active')
                try:
                    last_active_ts = int(last_active)
                except (TypeError, ValueError):
                    last_active_ts = now_ts

                if (now_ts - last_active_ts) > session_timeout:
                    logout_user()
                    session.clear()
                    if request.path.startswith('/api/'):
                        return jsonify({'error': 'Session expired'}), 401
                    return redirect(url_for('login'))

                session['_last_active'] = now_ts

            if request.method not in CSRF_UNSAFE_METHODS:
                return None

            if request.endpoint in ('static',):
                return None

            if _has_valid_csrf_token():
                return None

            logger.warning(
                f"CSRF validation failed for {request.method} {request.path} "
                f"from {request.remote_addr}"
            )

            if request.path.startswith('/api/'):
                return jsonify({'error': 'CSRF validation failed'}), 403

            return render_template(
                'login.html',
                error='Security validation failed. Refresh the page and try again.',
                show_password_notice=_should_show_password_change_notice()
            ), 403

        def _write_audit_log_async(level, module, message, timestamp, ip_address):
            # Run audit DB write in a background thread so a slow DB commit
            # cannot delay the HTTP response and trigger nginx upstream resets
            # ("Failed to fetch" in the browser).
            try:
                with app.app_context():
                    db.session.add(LogEntry(
                        level=level,
                        module=module,
                        message=message,
                        timestamp=timestamp,
                        ip_address=ip_address,
                    ))
                    db.session.commit()
            except Exception as audit_error:
                logger.warning(f"Async audit log write failed: {audit_error}")
                try:
                    db.session.rollback()
                except Exception:
                    pass

        @app.after_request
        def audit_state_changes(response):
            try:
                if request.method not in CSRF_UNSAFE_METHODS:
                    return response

                if not request.path.startswith('/api/'):
                    return response

                if response.status_code >= 400:
                    return response

                if not current_user.is_authenticated:
                    return response

                audit_summary = _summarize_audit_payload()
                audit_message = (
                    f"Admin {current_user.username} {request.method} {request.path}"
                )
                if audit_summary:
                    audit_message += f" payload={audit_summary}"

                threading.Thread(
                    target=_write_audit_log_async,
                    args=(
                        'INFO',
                        'audit',
                        audit_message,
                        int(time.time()),
                        _get_client_ip(),
                    ),
                    daemon=True,
                    name='gnss-caster-audit-write',
                ).start()
            except Exception as audit_error:
                logger.warning(f"Unable to schedule audit log: {audit_error}")

            return response
        
        # Routes
        @app.route('/')
        def index():
            if current_user.is_authenticated:
                return redirect(url_for('dashboard'))
            return redirect(url_for('login'))
        
        @app.route('/login', methods=['GET', 'POST'])
        def login():
            if current_user.is_authenticated:
                return redirect(url_for('dashboard'))

            show_password_notice = _should_show_password_change_notice()
            
            if request.method == 'POST':
                username = request.form.get('username', '').strip()
                password = request.form.get('password', '')
                client_ip = _get_client_ip()
                show_password_notice = _should_show_password_change_notice(username)

                blocked_for_seconds = _get_login_ip_block_seconds(client_ip)
                if blocked_for_seconds > 0:
                    return render_template(
                        'login.html',
                        error=f'Too many login attempts from this IP. Try again in {blocked_for_seconds} seconds.',
                        show_password_notice=show_password_notice
                    )
                
                logger.debug(f"Login attempt for user: {username}")
                
                user = Admin.query.filter_by(username=username).first()
                
                if user:
                    # Check if account is locked
                    if user.is_locked():
                        lock_time = user.locked_until - int(time.time())
                        return render_template('login.html', 
                                             error=f'Account locked. Try again in {lock_time} seconds.',
                                             show_password_notice=show_password_notice)
                    
                    # Check password
                    if bcrypt.check_password_hash(user.password, password):
                        # Fix #19: if this admin has 2FA enabled, don't complete
                        # login yet — stash a short-lived pending state and ask
                        # for the TOTP code on the next screen.
                        if getattr(user, 'totp_enabled', False) and getattr(user, 'totp_secret', ''):
                            user.last_login = int(time.time())
                            user.login_attempts = 0
                            user.locked_until = 0
                            db.session.commit()
                            _clear_login_ip_failures(client_ip)

                            session['_pending_2fa_user_id'] = user.id
                            session['_pending_2fa_version'] = int(user.session_version or 0)
                            session['_pending_2fa_at'] = int(time.time())
                            session['_pending_2fa_ip'] = client_ip
                            logger.info(f"User {username} passed password, awaiting 2FA from {client_ip}")
                            return redirect(url_for('login_2fa'))

                        # Successful login — update security fields in one commit,
                        # then respond immediately without a second blocking commit.
                        user.last_login = int(time.time())
                        user.login_attempts = 0
                        user.locked_until = 0
                        db.session.commit()
                        _clear_login_ip_failures(client_ip)

                        login_user(user)
                        session['_last_active'] = int(time.time())

                        logger.info(f"User {username} logged in successfully from {client_ip}")

                        # Write the audit log entry in a background thread so the
                        # redirect response is NOT held up by a slow SQLite commit
                        # (SQLite busy / NTRIP writer contention → nginx upstream
                        # reset → browser "page load error").
                        threading.Thread(
                            target=_write_audit_log_async,
                            args=('INFO', 'auth',
                                  f'User {username} logged in',
                                  int(time.time()), client_ip),
                            daemon=True,
                            name='gnss-caster-login-log',
                        ).start()

                        return redirect(url_for('dashboard'))
                    
                    # Failed login
                    user.login_attempts += 1
                    
                    # Lock account after too many attempts
                    if user.login_attempts >= config['security']['max_login_attempts']:
                        user.locked_until = int(time.time()) + config['security']['login_lockout_time']
                    
                    db.session.commit()

                blocked_for_seconds = _record_login_ip_failure(client_ip)

                # Write the failed-login entry asynchronously — the lock/attempt
                # state was already committed above; the log write does not need
                # to block the HTTP response.
                threading.Thread(
                    target=_write_audit_log_async,
                    args=('WARNING', 'auth',
                          f'Failed login attempt for user {username}',
                          int(time.time()), client_ip),
                    daemon=True,
                    name='gnss-caster-faillogin-log',
                ).start()

                logger.warning(f"Failed login attempt for user {username} from {client_ip}")
                return render_template(
                    'login.html',
                    error=(
                        f'Too many login attempts from this IP. Try again in {blocked_for_seconds} seconds.'
                        if blocked_for_seconds > 0 else
                        'Invalid username or password'
                    ),
                    show_password_notice=show_password_notice
                )
            
            return render_template('login.html', show_password_notice=show_password_notice)

        # ── TOTP 2FA helpers (Fix #19) ──────────────────────────────────────
        def _verify_totp_code(admin_user, code):
            """Verify a 6-digit TOTP code (with +/-1 step drift tolerance)."""
            try:
                import pyotp
            except Exception:
                logger.error("pyotp not installed — cannot verify 2FA")
                return False
            secret = str(getattr(admin_user, 'totp_secret', '') or '')
            if not secret:
                return False
            try:
                totp = pyotp.TOTP(secret)
                return totp.verify(str(code or '').strip(), valid_window=1)
            except Exception as totp_err:
                logger.warning(f"TOTP verification error: {totp_err}")
                return False

        def _verify_backup_code(admin_user, code):
            """Verify and consume a one-time backup code (bcrypt-hashed list)."""
            raw = str(code or '').strip().replace('-', '').replace(' ', '')
            if not raw:
                return False
            try:
                stored = json.loads(getattr(admin_user, 'totp_backup_codes', '') or '[]')
            except Exception:
                return False
            for idx, hashed in enumerate(stored):
                try:
                    if bcrypt.check_password_hash(hashed, raw):
                        # Consume: remove this code so it can't be reused.
                        stored.pop(idx)
                        admin_user.totp_backup_codes = json.dumps(stored)
                        db.session.commit()
                        return True
                except Exception:
                    continue
            return False

        @app.route('/login/2fa', methods=['GET', 'POST'])
        def login_2fa():
            # Must have a pending 2FA session from a successful password step.
            pending_id = session.get('_pending_2fa_user_id')
            pending_at = int(session.get('_pending_2fa_at', 0) or 0)

            # Expire the pending state after 5 minutes.
            if not pending_id or (int(time.time()) - pending_at) > 300:
                session.pop('_pending_2fa_user_id', None)
                session.pop('_pending_2fa_at', None)
                session.pop('_pending_2fa_ip', None)
                return redirect(url_for('login'))

            if current_user.is_authenticated:
                return redirect(url_for('dashboard'))

            user = Admin.query.get(pending_id)
            if not user or session.get('_pending_2fa_version') != int(user.session_version or 0):
                session.pop('_pending_2fa_version', None)
                session.pop('_pending_2fa_user_id', None)
                return redirect(url_for('login'))

            if request.method == 'POST':
                code = request.form.get('code', '').strip()
                client_ip = _get_client_ip()

                ok = _verify_totp_code(user, code)
                used_backup = False
                if not ok:
                    ok = _verify_backup_code(user, code)
                    used_backup = ok

                if ok:
                    session.pop('_pending_2fa_user_id', None)
                    session.pop('_pending_2fa_at', None)
                    session.pop('_pending_2fa_ip', None)

                    login_user(user)
                    session['_last_active'] = int(time.time())
                    logger.info(f"User {user.username} completed 2FA from {client_ip}"
                                + (" (backup code)" if used_backup else ""))

                    threading.Thread(
                        target=_write_audit_log_async,
                        args=('INFO', 'auth',
                              f'User {user.username} completed 2FA login'
                              + (' using a backup code' if used_backup else ''),
                              int(time.time()), client_ip),
                        daemon=True,
                        name='gnss-caster-2fa-log',
                    ).start()

                    if used_backup and window_low_backup_codes(user):
                        pass  # UI will warn separately
                    return redirect(url_for('dashboard'))

                logger.warning(f"Failed 2FA attempt for {user.username} from {client_ip}")
                threading.Thread(
                    target=_write_audit_log_async,
                    args=('WARNING', 'auth',
                          f'Failed 2FA attempt for user {user.username}',
                          int(time.time()), client_ip),
                    daemon=True,
                    name='gnss-caster-2fa-faillog',
                ).start()
                return render_template('login_2fa.html', error='Invalid authentication code')

            return render_template('login_2fa.html')

        def window_low_backup_codes(admin_user):
            try:
                stored = json.loads(getattr(admin_user, 'totp_backup_codes', '') or '[]')
                return len(stored) <= 2
            except Exception:
                return False

        @app.route('/api/auth/password_notice')
        def api_password_notice():
            """Password notice endpoint with anti-enumeration behavior."""
            try:
                # Prevent username enumeration. For unauthenticated clients,
                # always return a constant response.
                if not current_user.is_authenticated:
                    return jsonify({'show_password_notice': False})

                username = str(request.args.get('username', '')).strip()

                if username:
                    admin_user = Admin.query.filter_by(username=username).first()
                else:
                    admin_user = Admin.query.order_by(Admin.id.asc()).first()

                return jsonify({
                    'show_password_notice': bool(
                        admin_user and getattr(admin_user, 'must_change_password', False)
                    )
                })
            except Exception as notice_api_error:
                logger.warning(
                    f"Error in api_password_notice: {notice_api_error}"
                )
                return jsonify({'show_password_notice': False})
        
        @app.route('/logout', methods=['POST'])
        @login_required
        def logout():
            username_snapshot = str(current_user.username)
            client_ip_snapshot = _get_client_ip()

            logout_user()
            session.pop('_last_active', None)

            # Write logout entry asynchronously — same reason as login:
            # a slow SQLite commit must not block the redirect response.
            threading.Thread(
                target=_write_audit_log_async,
                args=('INFO', 'auth',
                      f'User {username_snapshot} logged out',
                      int(time.time()), client_ip_snapshot),
                daemon=True,
                name='gnss-caster-logout-log',
            ).start()

            return redirect(url_for('login'))
        
