                data = request.json or {}
                force = str(data.get('force', '')).strip().lower() in ('1', 'true', 'yes', 'on')
                renew_result = _renew_letsencrypt_certificates(force=force)
                refreshed_tls = _read_current_tls_configuration()
                client_ip = _get_client_ip()
                now_ts = int(time.time())

                db.session.add(LogEntry(
                    level='INFO',
                    module='tls',
                    message=(
                        f'User {current_user.username} triggered '
                        f'{"forced " if force else ""}Let\'s Encrypt renewal'
                    ),
                    timestamp=now_ts,
                    ip_address=client_ip
                ))
                db.session.commit()

                return jsonify({
                    'message': (
                        'Forced Let\'s Encrypt renewal completed'
                        if force else
                        'Let\'s Encrypt renewal completed'
                    ),
                    'result': renew_result,
                    'tls_info': refreshed_tls,
                }), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error renewing Let's Encrypt certificate: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/system/power/<action>', methods=['POST'])
        @login_required
        def api_system_power_action(action):
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                normalized_action = str(action or '').strip().lower()
                if normalized_action not in ('reboot', 'shutdown'):
                    return jsonify({'error': 'Unsupported power action'}), 400

                data = request.json or {}
                confirmation = str(data.get('confirm', '') or '').strip().lower()
                if confirmation != normalized_action:
                    return jsonify({
                        'error': f'Confirmation value must be "{normalized_action}"'
                    }), 400

                scheduled_action = _schedule_power_action(normalized_action)
                client_ip = _get_client_ip()
                now_ts = int(time.time())
                scheduler_label = str(
                    scheduled_action.get('scheduler', 'scheduler') or 'scheduler'
                )
                unit_label = str(scheduled_action.get('unit_name', '') or '').strip()
                action_detail = (
                    scheduler_label if not unit_label else f'{scheduler_label}, {unit_label}'
                )

                db.session.add(LogEntry(
                    level='WARNING',
                    module='power',
                    message=(
                        f'User {current_user.username} scheduled host '
                        f'{normalized_action} ({action_detail})'
                    ),
                    timestamp=now_ts,
                    ip_address=client_ip
                ))
                db.session.commit()

                return jsonify({
                    'message': (
                        f'Host {normalized_action} scheduled. '
                        f'The web interface and SSH session may disconnect in '
                        f'{scheduled_action.get("delay_seconds", 5)} seconds.'
                    ),
                    'action': normalized_action,
                    'scheduled': scheduled_action,
                }), 202
            except ValueError as validation_error:
                db.session.rollback()
                return jsonify({'error': str(validation_error)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error scheduling host power action {action}: {e}")
                return jsonify({'error': str(e)}), 500
        
        @app.route('/api/base_stations/<int:id>/position_history')
        @login_required
        def api_station_position_history(id):
            """Base position over time, for checking it stayed put."""
            try:
                from app.db.models import PositionSample

                try:
                    hours = max(1, min(168, int(request.args.get('hours', 24))))
                except (TypeError, ValueError):
                    hours = 24

                since = int(time.time()) - hours * 3600
                samples = (
                    PositionSample.query
                    .filter(PositionSample.station_id == id, PositionSample.ts >= since)
                    .order_by(PositionSample.ts)
                    .limit(2000)
                    .all()
                )

                offsets = [s.offset_m for s in samples if s.offset_m is not None]
                return jsonify({
                    'hours': hours,
                    'count': len(samples),
                    'max_offset_m': max(offsets) if offsets else None,
                    'mean_offset_m': (sum(offsets) / len(offsets)) if offsets else None,
                    'samples': [{
                        'ts': s.ts,
                        'latitude': s.latitude,
                        'longitude': s.longitude,
                        'altitude': s.altitude,
                        'offset_m': s.offset_m,
                        'satellites': s.satellites,
                        'hdop': s.hdop,
                        'fix_quality': s.fix_quality,
                    } for s in samples],
                })
            except Exception as e:
                logger.error(f'Error reading position history: {e}')
                return jsonify({'error': str(e)}), 500

