        @app.route('/api/2fa/status')
        @login_required
        def api_2fa_status():
            """Return whether 2FA is enabled for the current admin."""
            try:
                stored = json.loads(getattr(current_user, 'totp_backup_codes', '') or '[]')
            except Exception:
