        @app.route('/api/base_stations/<int:id>/stream')
        @login_required
        def api_base_station_stream(id):
            """
            Server-Sent Events: streams raw receiver output to the browser console.
            Events: data: <line>  |  event: error  |  event: ping
            """
            import select as _select, time as _time

            BaseStation.query.get_or_404(id)  # 404 if unknown station

            def _generate():
                from app.bluetooth.core import bluetooth_manager
                yield ': gnss-caster receiver stream\n\n'
                deadline_ping = _time.monotonic() + 15.0
                station_id = int(id)
                # Read from the console buffer the station loop fills, never
                # from the device itself: two readers on one handle meant the
                # console consumed RTCM bytes that were meant for the rovers.
                sequence = 0
                idle_since = _time.monotonic()

                while True:
                    try:
                        sequence, lines = bluetooth_manager.read_console_lines(
                            station_id, after_sequence=sequence
                        )
                    except Exception as read_err:
                        yield f'event: error\ndata: Read error: {read_err}\n\n'
                        break

                    if lines:
                        idle_since = _time.monotonic()
                        for text in lines:
                            yield f'data: {text}\n\n'
                    else:
                        _time.sleep(0.2)
                        # Only complain once the station has genuinely gone
                        # away, not on a momentary gap between sentences.
                        if _time.monotonic() - idle_since > 20.0:
                            with bluetooth_manager.lock:
                                still_connected = station_id in bluetooth_manager.device_files
                            if not still_connected:
                                yield 'event: error\ndata: Station not connected — no active receiver device\n\n'
                                break
                            idle_since = _time.monotonic()

                    now = _time.monotonic()
                    if now >= deadline_ping:
                        yield 'event: ping\ndata: ping\n\n'
                        deadline_ping = now + 15.0

            from flask import stream_with_context, Response
            return Response(
                stream_with_context(_generate()),
                mimetype='text/event-stream',
                headers={
                    'Cache-Control': 'no-cache',
                    # 'X-Accel-Buffering: no' stops nginx buffering the stream.
                    # Do NOT set 'Connection' here: PEP 3333 forbids hop-by-hop
                    # headers in a WSGI response, and waitress rejects the whole
                    # response with an AssertionError - which surfaced as
                    # "Stream error" in the receiver console.
                    'X-Accel-Buffering': 'no',
                },
            )

        @app.route('/api/events/dashboard')
        @login_required
        def api_events_dashboard():
            """Server-Sent Events feed of dashboard status (Fix #18).

            Pushes a combined bluetooth + NTRIP snapshot every few seconds so
            the dashboard can update live instead of polling on fixed timers.
            The stream self-terminates after a bounded lifetime so waitress
            worker threads are always eventually released; the browser simply
            reconnects (EventSource does this automatically).

            Event types:
              event: snapshot  data: {<combined status json>}
              event: ping      data: ping
            """
            import time as _time
            import json as _json

            # Bound the connection lifetime (browser auto-reconnects).
            max_lifetime_s = 300
            snapshot_interval_s = 3.0
            ping_interval_s = 20.0

            def _build_snapshot():
                from app.bluetooth.core import bluetooth_manager
                from app.ntrip.core import ntrip_server
                snap = {'ts': int(_time.time())}
                try:
                    snap['bluetooth'] = bluetooth_manager.get_status()
                except Exception as bt_err:
                    snap['bluetooth'] = {'error': str(bt_err)}
                try:
                    snap['ntrip'] = ntrip_server.get_status()
                except Exception as ntrip_err:
                    snap['ntrip'] = {'error': str(ntrip_err)}
                return snap

            def _generate():
                yield ': gnss-caster dashboard stream\n\n'
                started = _time.monotonic()
                last_snapshot = 0.0
                last_ping = _time.monotonic()

                while True:
                    now = _time.monotonic()

                    if (now - started) >= max_lifetime_s:
                        # Ask the client to reconnect and end cleanly.
                        yield 'event: reconnect\ndata: lifetime\n\n'
                        break

                    if (now - last_snapshot) >= snapshot_interval_s:
                        try:
                            payload = _json.dumps(_build_snapshot(), default=str)
                            yield f'event: snapshot\ndata: {payload}\n\n'
                        except Exception as snap_err:
                            yield f'event: error\ndata: {snap_err}\n\n'
                        last_snapshot = now
                        last_ping = now

                    if (now - last_ping) >= ping_interval_s:
                        yield 'event: ping\ndata: ping\n\n'
                        last_ping = now

                    _time.sleep(0.5)

            from flask import stream_with_context, Response
            return Response(
                stream_with_context(_generate()),
                mimetype='text/event-stream',
                headers={
                    'Cache-Control': 'no-cache',
                    # 'X-Accel-Buffering: no' stops nginx buffering the stream.
                    # Do NOT set 'Connection' here: PEP 3333 forbids hop-by-hop
                    # headers in a WSGI response, and waitress rejects the whole
                    # response with an AssertionError - which surfaced as
                    # "Stream error" in the receiver console.
                    'X-Accel-Buffering': 'no',
                },
            )

        @app.route('/api/bluetooth/status')
        @api_token_or_login_required
        def api_bluetooth_status():
            try:
                from app.bluetooth.core import bluetooth_manager
                status = bluetooth_manager.get_status()
                return jsonify(status)
            except Exception as e:
                logger.error(f"Error getting Bluetooth status: {e}")
                return jsonify({'error': str(e)}), 500
        
        # Template filter for timestamp formatting
        @app.template_filter('timestamp_to_date')
        def timestamp_to_date(timestamp):
            from datetime import datetime
            try:
                if timestamp:
                    return datetime.fromtimestamp(int(timestamp)).strftime('%Y-%m-%d %H:%M:%S')
            except Exception:
                pass
            return 'N/A'
        
        @app.template_filter('timestamp_to_relative')
        def timestamp_to_relative(timestamp):
            from datetime import datetime
            try:
                if timestamp:
                    now = datetime.now()
                    then = datetime.fromtimestamp(int(timestamp))
                    diff = now - then
                    
                    if diff.days > 365:
                        return f"{diff.days // 365} years ago"
                    elif diff.days > 30:
                        return f"{diff.days // 30} months ago"
                    elif diff.days > 0:
                        return f"{diff.days} days ago"
                    elif diff.seconds > 3600:
                        return f"{diff.seconds // 3600} hours ago"
                    elif diff.seconds > 60:
                        return f"{diff.seconds // 60} minutes ago"
                    else:
                        return "just now"
            except Exception:
                pass
            return 'N/A'
        
        # Error handlers
        @app.errorhandler(404)
        def not_found_error(error):
            return render_template('404.html'), 404
        
        @app.errorhandler(500)
        def internal_error(error):
            logger.error(f"Internal server error: {error}")
            return render_template('500.html'), 500

        def _get_table_columns(table_name):
            return [
                row[1]
                for row in db.session.execute(text(f"PRAGMA table_info({table_name})")).fetchall()
            ]

        def _migration_001_admin_notice_flag():
            admin_columns = _get_table_columns('admin')
            if 'must_change_password' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN must_change_password INTEGER DEFAULT 0")
                )

        def _migration_003_admin_roles():
            admin_columns = _get_table_columns('admin')
            if 'role' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN role TEXT DEFAULT 'admin'")
                )

            db.session.execute(
                text("UPDATE admin SET role = 'admin' WHERE role IS NULL OR role = ''")
            )

        def _migration_004_base_station_command_strategy():
            base_station_columns = _get_table_columns('base_station')
            if 'command_strategy' not in base_station_columns:
                db.session.execute(
                    text("ALTER TABLE base_station ADD COLUMN command_strategy TEXT DEFAULT 'generated'")
                )

            # Legacy semantics: non-empty startup/shutdown command text meant a
            # full override of generated defaults. Preserve that behavior by
            # marking such rows as replace-mode during migration.
            db.session.execute(text("""
                UPDATE base_station
                SET command_strategy = CASE
                    WHEN (startup_commands IS NOT NULL AND TRIM(startup_commands) <> '')
                      OR (shutdown_commands IS NOT NULL AND TRIM(shutdown_commands) <> '')
                    THEN 'replace'
                    ELSE 'generated'
                END
                WHERE command_strategy IS NULL OR TRIM(command_strategy) = ''
            """))

        def _migration_005_base_station_receiver_brand_and_survey():
            base_station_columns = _get_table_columns('base_station')
            if 'receiver_brand' not in base_station_columns:
                db.session.execute(
                    text("ALTER TABLE base_station ADD COLUMN receiver_brand TEXT DEFAULT 'comnav'")
                )
            if 'survey_duration_sec' not in base_station_columns:
                db.session.execute(
                    text("ALTER TABLE base_station ADD COLUMN survey_duration_sec INTEGER DEFAULT 30")
                )

            db.session.execute(text("""
                UPDATE base_station
                SET receiver_brand = 'comnav'
                WHERE receiver_brand IS NULL OR TRIM(receiver_brand) = ''
            """))

            db.session.execute(text("""
                UPDATE base_station
                SET survey_duration_sec = 30
                WHERE survey_duration_sec IS NULL OR survey_duration_sec < 15 OR survey_duration_sec > 300
            """))

        def _migration_002_base_station_transport_fields():
            base_station_columns = _get_table_columns('base_station')
            required_base_station_columns = [
                ('connection_type', "TEXT DEFAULT 'bluetooth'"),
                ('gnss_port', "TEXT DEFAULT '/dev/rfcomm1'"),
                ('baudrate', 'INTEGER DEFAULT 115200'),
                ('data_bits', 'INTEGER DEFAULT 8'),
                ('stop_bits', 'INTEGER DEFAULT 1'),
                ('parity', "TEXT DEFAULT 'N'"),
                ('data_type', "TEXT DEFAULT 'RTCM3'"),
                ('output_interval', 'INTEGER DEFAULT 1'),
                ('position_mode', "TEXT DEFAULT 'auto'"),
                ('position_accuracy', 'REAL DEFAULT 1.0'),
                ('manual_lat', 'REAL DEFAULT 0.0'),
                ('manual_lon', 'REAL DEFAULT 0.0'),
                ('manual_alt', 'REAL DEFAULT 0.0'),
                ('operation_mode', "TEXT DEFAULT 'base'"),
                ('receiver_brand', "TEXT DEFAULT 'comnav'"),
                ('survey_duration_sec', 'INTEGER DEFAULT 30'),
                ('antenna_height', 'REAL DEFAULT 0.0'),
                ('add_antenna_height', 'BOOLEAN DEFAULT 0'),
                ('receiver_model', "TEXT DEFAULT ''"),
                ('firmware_version', "TEXT DEFAULT ''"),
                ('firmware_date', "TEXT DEFAULT ''"),
                ('receiver_serial', "TEXT DEFAULT ''"),
                ('antenna_type', "TEXT DEFAULT ''"),
                ('antenna_serial', "TEXT DEFAULT ''"),
                ('command_strategy', "TEXT DEFAULT 'generated'"),
                ('startup_commands', "TEXT DEFAULT ''"),
                ('shutdown_commands', "TEXT DEFAULT ''")
            ]

            for column_name, column_def in required_base_station_columns:
                if column_name in base_station_columns:
                    continue
                db.session.execute(
                    text(f"ALTER TABLE base_station ADD COLUMN {column_name} {column_def}")
                )

        def _migration_006_admin_totp():
            admin_columns = _get_table_columns('admin')
            if 'totp_secret' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN totp_secret TEXT DEFAULT ''")
                )
            if 'totp_enabled' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN totp_enabled INTEGER DEFAULT 0")
                )
            if 'totp_backup_codes' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN totp_backup_codes TEXT DEFAULT ''")
                )

        def _migration_007_pending_totp():
            admin_columns = _get_table_columns('admin')
            if 'totp_pending_secret' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN totp_pending_secret TEXT DEFAULT ''")
                )
            if 'totp_pending_expires' not in admin_columns:
                db.session.execute(
                    text("ALTER TABLE admin ADD COLUMN totp_pending_expires INTEGER DEFAULT 0")
                )

        def _migration_008_session_version():
            if 'session_version' not in _get_table_columns('admin'):
                db.session.execute(text('ALTER TABLE admin ADD COLUMN session_version INTEGER NOT NULL DEFAULT 0'))

        def _run_schema_migrations():
            migrations = [
                (1, 'admin.must_change_password', _migration_001_admin_notice_flag),
                (2, 'base_station.transport_and_position_fields', _migration_002_base_station_transport_fields),
                (3, 'admin.roles', _migration_003_admin_roles),
                (4, 'base_station.command_strategy', _migration_004_base_station_command_strategy),
                (5, 'base_station.receiver_brand_and_survey_duration', _migration_005_base_station_receiver_brand_and_survey),
                (6, 'admin.totp_2fa', _migration_006_admin_totp),
                (7, 'admin.pending_totp', _migration_007_pending_totp),
                (8, 'admin.session_version', _migration_008_session_version),
            ]

            db.session.execute(text("""
                CREATE TABLE IF NOT EXISTS schema_migration (
                    version INTEGER PRIMARY KEY,
                    name TEXT NOT NULL,
                    applied_at INTEGER NOT NULL
                )
            """))
            db.session.commit()

            already_applied = {
                int(row[0])
                for row in db.session.execute(
                    text("SELECT version FROM schema_migration ORDER BY version ASC")
                ).fetchall()
            }
            newly_applied = set()

            for version, migration_name, migration_handler in migrations:
                if version in already_applied:
                    continue

                logger.info(f"Applying schema migration {version}: {migration_name}")
                try:
                    migration_handler()
                    db.session.execute(
                        text(
                            "INSERT INTO schema_migration (version, name, applied_at) "
                            "VALUES (:version, :name, :applied_at)"
                        ),
                        {
                            'version': int(version),
                            'name': str(migration_name),
                            'applied_at': int(time.time()),
                        }
                    )
                    db.session.commit()
                    newly_applied.add(int(version))
                except Exception as migration_error:
                    db.session.rollback()
                    logger.error(
                        f"Schema migration {version} failed ({migration_name}): {migration_error}"
                    )
                    raise

            return newly_applied
        
        # Initialize database
        with app.app_context():
            logger.debug("Creating database tables...")
            db.create_all()
            _run_schema_migrations()
            _ensure_built_in_admin(config['security']['admin_default_user'])
            _migrate_legacy_rover_passwords()
            
            # Initialize default RTCM settings
            if not RTCMSetting.query.first():
                logger.debug("Initializing default RTCM settings...")
                
                for msg_type, description in RTCM_DESCRIPTIONS.items():
                    setting = RTCMSetting(
                        msg_type=msg_type,
                        enabled=is_default_rtcm_enabled(msg_type),
                        description=description,
                        version='3.2',
                        group=get_message_group(msg_type)
                    )
                    db.session.add(setting)
                
                db.session.commit()
                logger.info("Default RTCM settings initialized")
            
            # Initialize system settings
            if not SystemSetting.query.first():
                logger.debug("Initializing system settings...")

                default_hostname = ''
                try:
                    if hasattr(os, 'uname'):
                        default_hostname = os.uname().nodename
                except Exception:
                    default_hostname = ''

                if not default_hostname:
                    default_hostname = os.environ.get('HOSTNAME', '') or 'gnss-caster'
                
                default_settings = [
                    ('system_name', default_hostname, 'System name'),
                    ('system_version', __version__, 'System version'),
                    ('ntrip_enabled', 'true', 'NTRIP server enabled'),
                    ('bluetooth_enabled', 'true', 'Bluetooth enabled'),
                    ('bluetooth_name', 'RPI-Caster-GNSS', 'Bluetooth adapter visible name'),
                    ('bluetooth_discoverable', 'true', 'Bluetooth adapter discoverable mode'),
                    ('auto_backup', 'true', 'Automatic backups enabled'),
                    ('backup_interval', '86400', 'Backup interval in seconds'),
                    ('log_retention', '30', 'Log retention in days'),
                    ('backup_external_path', '', 'Second backup destination (USB or network mount); empty disables it'),
                    ('telegram_enabled', 'false', 'Send Telegram notifications'),
                    ('telegram_bot_token', '', 'Telegram bot token from @BotFather'),
                    ('telegram_chat_id', '', 'Telegram chat or channel ID to notify'),
                    ('telegram_admin_id', '', 'Telegram chat ID allowed to send commands'),
                    ('telegram_commands_enabled', 'false', 'Accept commands from the admin chat'),
                    ('telegram_send_backup', 'false', 'Upload the backup archive to the chat'),
                    ('backup_encryption_enabled', 'false', 'Encrypt backup archives with AES-256'),
                    ('gnss_time_sync', 'false', 'Set the system clock from the GNSS receiver'),
                    ('backup_encryption_passphrase', '', 'Passphrase used to encrypt backups'),
                    ('notify_station_up', 'true', 'Notify when a station connects'),
                    ('notify_station_down', 'true', 'Notify when a station disconnects'),
                    ('notify_station_error', 'true', 'Notify on station errors'),
                    ('notify_rover_connect', 'false', 'Notify when a rover connects'),
                    ('notify_rover_disconnect', 'false', 'Notify when a rover disconnects'),
                    ('notify_backup', 'true', 'Notify about backup results'),
                    ('notify_service', 'true', 'Notify on service start/stop'),
                    ('max_connections', '100', 'Maximum concurrent connections'),
                    ('data_retention', '365', 'Data retention in days')
                ]
                
                for key, value, description in default_settings:
                    setting = SystemSetting(
                        key=key,
                        value=value,
                        description=description
                    )
                    db.session.add(setting)
                
                db.session.commit()
                logger.info("System settings initialized")

            # Ensure settings added in newer versions exist on upgraded systems.
            required_settings = [
                ('ntrip_enabled', 'true', 'NTRIP server enabled'),
                ('bluetooth_enabled', 'true', 'Bluetooth enabled'),
                ('bluetooth_name', 'RPI-Caster-GNSS', 'Bluetooth adapter visible name'),
                ('bluetooth_discoverable', 'true', 'Bluetooth adapter discoverable mode'),
                ('auto_backup', 'true', 'Automatic backups enabled'),
                ('backup_interval', '86400', 'Backup interval in seconds'),
                ('log_retention', '30', 'Log retention in days'),
                ('backup_external_path', '', 'Second backup destination (USB or network mount); empty disables it'),
                    ('telegram_enabled', 'false', 'Send Telegram notifications'),
                    ('telegram_bot_token', '', 'Telegram bot token from @BotFather'),
                    ('telegram_chat_id', '', 'Telegram chat or channel ID to notify'),
                    ('telegram_admin_id', '', 'Telegram chat ID allowed to send commands'),
                    ('telegram_commands_enabled', 'false', 'Accept commands from the admin chat'),
                    ('telegram_send_backup', 'false', 'Upload the backup archive to the chat'),
                    ('backup_encryption_enabled', 'false', 'Encrypt backup archives with AES-256'),
                    ('gnss_time_sync', 'false', 'Set the system clock from the GNSS receiver'),
                    ('backup_encryption_passphrase', '', 'Passphrase used to encrypt backups'),
                    ('notify_station_up', 'true', 'Notify when a station connects'),
                    ('notify_station_down', 'true', 'Notify when a station disconnects'),
                    ('notify_station_error', 'true', 'Notify on station errors'),
                    ('notify_rover_connect', 'false', 'Notify when a rover connects'),
                    ('notify_rover_disconnect', 'false', 'Notify when a rover disconnects'),
                    ('notify_backup', 'true', 'Notify about backup results'),
                    ('notify_service', 'true', 'Notify on service start/stop'),
                ('max_connections', '100', 'Maximum concurrent connections'),
                ('data_retention', '365', 'Data retention in days')
            ]

            missing_created = 0
            for key, value, description in required_settings:
                existing_setting = SystemSetting.query.filter_by(key=key).first()
                if existing_setting:
                    continue
                db.session.add(SystemSetting(
                    key=key,
                    value=value,
                    description=description
                ))
                missing_created += 1

            if missing_created > 0:
                db.session.commit()
                logger.info(f"Added {missing_created} missing system settings")

            # Migrate legacy auto-filled receiver commands to auto mode so that
            # global RTCM Settings can become the primary source of truth.
            migrated_receiver_defaults = 0
            try:
                from app.bluetooth.core import bluetooth_manager

                bluetooth_manager.init_app(app)

                for station in BaseStation.query.order_by(BaseStation.id.asc()).all():
                    defaults = bluetooth_manager.get_receiver_command_defaults(station)
                    startup_default = str(defaults.get('startup', '') or '').strip()
                    shutdown_default = str(defaults.get('shutdown', '') or '').strip()
                    current_startup = str(getattr(station, 'startup_commands', '') or '').strip()
                    current_shutdown = str(getattr(station, 'shutdown_commands', '') or '').strip()
                    changed = False

                    if current_startup and current_startup == startup_default:
                        station.startup_commands = ''
                        changed = True

                    if current_shutdown and current_shutdown == shutdown_default:
                        station.shutdown_commands = ''
                        changed = True

                    if changed:
                        station.updated_at = int(time.time())
                        migrated_receiver_defaults += 1

                if migrated_receiver_defaults > 0:
                    db.session.commit()
                    logger.info(
                        f"Migrated {migrated_receiver_defaults} base stations to RTCM Settings auto mode"
                    )
            except Exception as receiver_defaults_migration_error:
                logger.warning(
                    f"Unable to migrate legacy receiver command defaults: "
                    f"{receiver_defaults_migration_error}"
                )
        
        logger.info("Flask application created successfully")
        return app
        
    except Exception as e:
        logger.error(f"Failed to create Flask app: {e}", exc_info=True)
        raise
EOF

